begin;

do $$
begin
  if not exists (select 1 from pg_catalog.pg_roles where rolname = 'pac_app_runtime') then
    raise exception 'Required least-privilege role pac_app_runtime is missing';
  end if;
  if to_regprocedure('pac.assert_plain_page_text(text)') is null
    or to_regprocedure('pac.assert_safe_page_link(text)') is null then
    raise exception 'Required trusted page-copy validation functions are missing';
  end if;
end;
$$;

-- Fixed UTF-8 encoding makes the document digest independent of pgcrypto's
-- installation schema (Supabase may install extensions outside public).
create or replace function pac.surface_document_hash(value text)
returns text language sql immutable strict parallel safe
set search_path = pg_catalog
as $$ select encode(sha256(convert_to(value, 'UTF8')), 'hex') $$;

create table if not exists pac.surface_definitions (
  surface_id text primary key check (surface_id ~ '^[a-z0-9][a-z0-9.-]{0,159}$'),
  route_pattern text not null,
  staff_label text not null,
  scope_policy text not null check (scope_policy in ('inheritable', 'one-dhs', 'dsd')),
  schema_version integer not null default 1 check (schema_version = 1),
  field_contract jsonb not null,
  protected_fields text[] not null default '{}'::text[],
  required_review_dimensions text[] not null,
  linked_content_item_id text references pac.content_items(content_item_id),
  active boolean not null default true,
  registered_at timestamptz not null default now(),
  registered_by text not null,
  check (jsonb_typeof(field_contract) = 'array'),
  check (jsonb_array_length(field_contract) between 1 and 500),
  check (cardinality(required_review_dimensions) > 0),
  check (required_review_dimensions <@ array[
    'language_alignment', 'factual_currentness', 'accessibility', 'scope',
    'placement', 'rights_and_consent', 'community_representation', 'legal_policy'
  ]::text[])
);

create table if not exists pac.surface_revisions (
  revision_id uuid primary key default gen_random_uuid(),
  surface_id text not null references pac.surface_definitions(surface_id),
  scope_id text not null references pac.program_scopes(scope_id)
    check (scope_id in ('one-dhs', 'dsd')),
  revision_number integer not null check (revision_number > 0),
  document jsonb not null,
  document_sha256 text generated always as (
    pac.surface_document_hash(document::text)
  ) stored,
  change_note text not null,
  required_review_dimensions text[] not null,
  created_at timestamptz not null default now(),
  created_by text not null,
  based_on_revision_id uuid references pac.surface_revisions(revision_id),
  unique (surface_id, scope_id, revision_number),
  unique (revision_id, surface_id, scope_id),
  check (cardinality(required_review_dimensions) > 0)
);

create index if not exists surface_revisions_lookup_idx
  on pac.surface_revisions(surface_id, scope_id, revision_number desc);

create table if not exists pac.surface_reviews (
  review_id uuid primary key default gen_random_uuid(),
  revision_id uuid not null references pac.surface_revisions(revision_id),
  dimension text not null check (
    dimension in (
      'language_alignment', 'factual_currentness', 'accessibility', 'scope',
      'placement', 'rights_and_consent', 'community_representation', 'legal_policy'
    )
  ),
  status text not null check (status in ('pending', 'pass', 'revise', 'blocked', 'not_applicable')),
  note text,
  reviewer_role text not null,
  reviewer_id text,
  recorded_at timestamptz not null default now(),
  supersedes_review_id uuid references pac.surface_reviews(review_id)
);

create index if not exists surface_reviews_lookup_idx
  on pac.surface_reviews(revision_id, dimension, recorded_at desc, review_id desc);

create table if not exists pac.surface_publication_decisions (
  publication_decision_id bigint generated always as identity primary key,
  surface_id text not null references pac.surface_definitions(surface_id),
  scope_id text not null references pac.program_scopes(scope_id)
    check (scope_id in ('one-dhs', 'dsd')),
  revision_id uuid references pac.surface_revisions(revision_id),
  decision text not null check (decision in ('publish', 'withdraw', 'inherit')),
  gate_snapshot jsonb not null,
  reason text not null,
  decided_at timestamptz not null default now(),
  decided_by text not null,
  check (decision <> 'publish' or revision_id is not null),
  check (decision <> 'inherit' or (scope_id = 'dsd' and revision_id is null))
);

create index if not exists surface_publication_decisions_lookup_idx
  on pac.surface_publication_decisions(surface_id, scope_id, publication_decision_id desc);

create table if not exists pac.surface_change_events (
  event_id bigint generated always as identity primary key,
  surface_id text not null references pac.surface_definitions(surface_id),
  scope_id text not null references pac.program_scopes(scope_id)
    check (scope_id in ('one-dhs', 'dsd')),
  revision_id uuid references pac.surface_revisions(revision_id),
  publication_decision_id bigint references pac.surface_publication_decisions(publication_decision_id),
  action text not null check (
    action in ('draft_created', 'review_recorded', 'published', 'withdrawn', 'inheritance_resumed', 'restored')
  ),
  detail jsonb not null default '{}'::jsonb,
  occurred_at timestamptz not null default now(),
  actor_id text not null,
  actor_role text not null
);

create index if not exists surface_change_events_lookup_idx
  on pac.surface_change_events(surface_id, scope_id, event_id desc);

create or replace function pac.prevent_surface_history_change()
returns trigger
language plpgsql
set search_path = pg_catalog, pac
as $$
begin
  raise exception 'Editable surface history is append-only' using errcode = '55000';
end;
$$;

drop trigger if exists surface_revisions_append_only on pac.surface_revisions;
create trigger surface_revisions_append_only
before update or delete on pac.surface_revisions
for each row execute function pac.prevent_surface_history_change();

drop trigger if exists surface_reviews_append_only on pac.surface_reviews;
create trigger surface_reviews_append_only
before update or delete on pac.surface_reviews
for each row execute function pac.prevent_surface_history_change();

drop trigger if exists surface_publication_decisions_append_only on pac.surface_publication_decisions;
create trigger surface_publication_decisions_append_only
before update or delete on pac.surface_publication_decisions
for each row execute function pac.prevent_surface_history_change();

drop trigger if exists surface_change_events_append_only on pac.surface_change_events;
create trigger surface_change_events_append_only
before update or delete on pac.surface_change_events
for each row execute function pac.prevent_surface_history_change();

create or replace function pac.assert_surface_request(
  requested_scope_id text,
  requested_surface_id text,
  for_mutation boolean default false
)
returns void
language plpgsql
stable
set search_path = pg_catalog, pac
as $$
declare
  definition pac.surface_definitions%rowtype;
begin
  if requested_scope_id not in ('one-dhs', 'dsd')
    or not exists (
      select 1 from pac.program_scopes scope_record
      where scope_record.scope_id = requested_scope_id and scope_record.active = true
    ) then
    raise exception 'Unknown or inactive program scope' using errcode = '22023';
  end if;

  select * into definition
  from pac.surface_definitions
  where surface_id = requested_surface_id and active = true;
  if not found then
    raise exception 'This page area is not available' using errcode = 'P0002';
  end if;

  if for_mutation then
    if definition.scope_policy = 'one-dhs' and requested_scope_id <> 'one-dhs' then
      raise exception 'This page area belongs to One DHS' using errcode = '42501';
    end if;
    if definition.scope_policy = 'dsd' and requested_scope_id <> 'dsd' then
      raise exception 'This page area belongs to One DSD' using errcode = '42501';
    end if;
  else
    if definition.scope_policy = 'dsd' and requested_scope_id <> 'dsd' then
      raise exception 'This page area belongs to One DSD' using errcode = '42501';
    end if;
  end if;
end;
$$;

create or replace function pac.assert_valid_surface_document(
  requested_surface_id text,
  requested_scope_id text,
  requested_document jsonb
)
returns void
language plpgsql
stable
set search_path = pg_catalog, pac
as $$
declare
  definition pac.surface_definitions%rowtype;
  field_definition jsonb;
  field_key text;
  field_kind text;
  field_required boolean;
  field_maximum integer;
  item_maximum integer;
  field_value jsonb;
  text_value text;
  list_item jsonb;
  block_item jsonb;
  link_item jsonb;
  block_type text;
  expected_keys text[];
begin
  perform pac.assert_surface_request(requested_scope_id, requested_surface_id, true);
  select * into strict definition
  from pac.surface_definitions
  where surface_id = requested_surface_id and active = true;

  if requested_document is null or jsonb_typeof(requested_document) <> 'object'
    or octet_length(convert_to(requested_document::text, 'UTF8')) > 1000000 then
    raise exception 'Page wording must be a complete, reasonably sized document' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_object_keys(requested_document) actual(name)
    where actual.name <> all(array['schemaVersion', 'surfaceId', 'scope', 'values']::text[])
  ) or not requested_document ?& array['schemaVersion', 'surfaceId', 'scope', 'values']::text[] then
    raise exception 'Page wording document fields are not allowed' using errcode = '22023';
  end if;
  if jsonb_typeof(requested_document -> 'schemaVersion') <> 'number'
    or (requested_document ->> 'schemaVersion')::integer <> definition.schema_version
    or requested_document ->> 'surfaceId' <> requested_surface_id
    or requested_document ->> 'scope' <> requested_scope_id
    or jsonb_typeof(requested_document -> 'values') <> 'object' then
    raise exception 'Page wording document identity does not match this page area' using errcode = '22023';
  end if;

  select array_agg(field ->> 'key' order by ordinal)
  into expected_keys
  from jsonb_array_elements(definition.field_contract) with ordinality registered(field, ordinal);
  if expected_keys is null
    or not (requested_document -> 'values') ?& expected_keys
    or exists (
      select 1 from jsonb_object_keys(requested_document -> 'values') actual(name)
      where actual.name <> all(expected_keys)
    ) then
    raise exception 'Page wording fields do not match this page area' using errcode = '22023';
  end if;

  for field_definition in select value from jsonb_array_elements(definition.field_contract)
  loop
    field_key := field_definition ->> 'key';
    field_kind := field_definition ->> 'kind';
    field_required := coalesce((field_definition ->> 'required')::boolean, true);
    field_maximum := coalesce((field_definition ->> 'maxLength')::integer,
      case when field_kind = 'short' then 500 when field_kind = 'url' then 2000 else 10000 end);
    item_maximum := coalesce((field_definition ->> 'maxItems')::integer, 100);
    field_value := requested_document -> 'values' -> field_key;

    if field_kind in ('short', 'long', 'url') then
      if jsonb_typeof(field_value) <> 'string' then
        raise exception 'A page wording field has the wrong kind of value' using errcode = '22023';
      end if;
      text_value := field_value #>> '{}';
      if length(text_value) > field_maximum or (field_required and length(btrim(text_value)) = 0) then
        raise exception 'A page wording field is blank or too long' using errcode = '22023';
      end if;
      if length(btrim(text_value)) > 0 then
        if field_kind = 'url' then
          perform pac.assert_safe_page_link(text_value);
        else
          perform pac.assert_plain_page_text(text_value);
        end if;
      end if;
      continue;
    end if;

    if jsonb_typeof(field_value) <> 'array'
      or jsonb_array_length(field_value) > item_maximum
      or (field_required and jsonb_array_length(field_value) = 0) then
      raise exception 'A page wording list is empty, too long, or has the wrong kind of value' using errcode = '22023';
    end if;

    if field_kind = 'string-list' then
      for list_item in select value from jsonb_array_elements(field_value)
      loop
        if jsonb_typeof(list_item) <> 'string' then
          raise exception 'A page wording list must contain text' using errcode = '22023';
        end if;
        text_value := list_item #>> '{}';
        if length(btrim(text_value)) = 0 or length(text_value) > field_maximum then
          raise exception 'A page wording list item is blank or too long' using errcode = '22023';
        end if;
        perform pac.assert_plain_page_text(text_value);
      end loop;
    elsif field_kind = 'link-list' then
      for link_item in select value from jsonb_array_elements(field_value)
      loop
        if jsonb_typeof(link_item) <> 'object'
          or not link_item ?& array['label', 'href']::text[]
          or exists (
            select 1 from jsonb_object_keys(link_item) actual(name)
            where actual.name <> all(array['label', 'href']::text[])
          ) or jsonb_typeof(link_item -> 'label') <> 'string'
          or jsonb_typeof(link_item -> 'href') <> 'string' then
          raise exception 'A page wording link has fields that are not allowed' using errcode = '22023';
        end if;
        text_value := link_item ->> 'label';
        if length(btrim(text_value)) = 0 or length(text_value) > field_maximum then
          raise exception 'A page wording link label is blank or too long' using errcode = '22023';
        end if;
        perform pac.assert_plain_page_text(text_value);
        perform pac.assert_safe_page_link(link_item ->> 'href');
      end loop;
    elsif field_kind = 'rich-blocks' then
      for block_item in select value from jsonb_array_elements(field_value)
      loop
        if jsonb_typeof(block_item) <> 'object' or jsonb_typeof(block_item -> 'type') <> 'string' then
          raise exception 'A structured page section has fields that are not allowed' using errcode = '22023';
        end if;
        block_type := block_item ->> 'type';
        if block_type = 'heading' then
          if not block_item ?& array['type', 'level', 'text']::text[]
            or exists (
              select 1 from jsonb_object_keys(block_item) actual(name)
              where actual.name <> all(array['type', 'level', 'text']::text[])
            ) or jsonb_typeof(block_item -> 'level') <> 'number'
            or (block_item ->> 'level')::integer not in (2, 3)
            or jsonb_typeof(block_item -> 'text') <> 'string' then
            raise exception 'A structured heading has fields that are not allowed' using errcode = '22023';
          end if;
          text_value := block_item ->> 'text';
          if length(btrim(text_value)) = 0 or length(text_value) > field_maximum then
            raise exception 'A structured heading is blank or too long' using errcode = '22023';
          end if;
          perform pac.assert_plain_page_text(text_value);
        elsif block_type = 'paragraph' then
          if not block_item ?& array['type', 'text']::text[]
            or exists (
              select 1 from jsonb_object_keys(block_item) actual(name)
              where actual.name <> all(array['type', 'text']::text[])
            ) or jsonb_typeof(block_item -> 'text') <> 'string' then
            raise exception 'A structured paragraph has fields that are not allowed' using errcode = '22023';
          end if;
          text_value := block_item ->> 'text';
          if length(btrim(text_value)) = 0 or length(text_value) > field_maximum then
            raise exception 'A structured paragraph is blank or too long' using errcode = '22023';
          end if;
          perform pac.assert_plain_page_text(text_value);
        elsif block_type in ('bullet-list', 'numbered-list') then
          if not block_item ?& array['type', 'items']::text[]
            or exists (
              select 1 from jsonb_object_keys(block_item) actual(name)
              where actual.name <> all(array['type', 'items']::text[])
            ) or jsonb_typeof(block_item -> 'items') <> 'array'
            or jsonb_array_length(block_item -> 'items') not between 1 and item_maximum then
            raise exception 'A structured list has fields that are not allowed' using errcode = '22023';
          end if;
          for list_item in select value from jsonb_array_elements(block_item -> 'items')
          loop
            if jsonb_typeof(list_item) <> 'string' then
              raise exception 'A structured list must contain text' using errcode = '22023';
            end if;
            text_value := list_item #>> '{}';
            if length(btrim(text_value)) = 0 or length(text_value) > field_maximum then
              raise exception 'A structured list item is blank or too long' using errcode = '22023';
            end if;
            perform pac.assert_plain_page_text(text_value);
          end loop;
        elsif block_type = 'link-list' then
          if not block_item ?& array['type', 'items']::text[]
            or exists (
              select 1 from jsonb_object_keys(block_item) actual(name)
              where actual.name <> all(array['type', 'items']::text[])
            ) or jsonb_typeof(block_item -> 'items') <> 'array'
            or jsonb_array_length(block_item -> 'items') not between 1 and item_maximum then
            raise exception 'A structured link list has fields that are not allowed' using errcode = '22023';
          end if;
          for link_item in select value from jsonb_array_elements(block_item -> 'items')
          loop
            if jsonb_typeof(link_item) <> 'object'
              or not link_item ?& array['label', 'href']::text[]
              or exists (
                select 1 from jsonb_object_keys(link_item) actual(name)
                where actual.name <> all(array['label', 'href']::text[])
              ) or jsonb_typeof(link_item -> 'label') <> 'string'
              or jsonb_typeof(link_item -> 'href') <> 'string' then
              raise exception 'A structured link has fields that are not allowed' using errcode = '22023';
            end if;
            text_value := link_item ->> 'label';
            if length(btrim(text_value)) = 0 or length(text_value) > field_maximum then
              raise exception 'A structured link label is blank or too long' using errcode = '22023';
            end if;
            perform pac.assert_plain_page_text(text_value);
            perform pac.assert_safe_page_link(link_item ->> 'href');
          end loop;
        else
          raise exception 'A structured page section is not allowed' using errcode = '22023';
        end if;
      end loop;
    else
      raise exception 'A registered page wording field kind is not supported' using errcode = '22023';
    end if;
  end loop;
end;
$$;

create or replace function pac.enforce_surface_definition_contract()
returns trigger
language plpgsql
set search_path = pg_catalog, pac
as $$
declare
  field_definition jsonb;
  field_key text;
  field_kind text;
  keys text[] := '{}'::text[];
  protected_key text;
begin
  if new.route_pattern <> '*' and new.route_pattern !~ '^/[^[:space:][:cntrl:]<>"\\]*$' then
    raise exception 'Registered page route is not safe' using errcode = '22023';
  end if;
  perform pac.assert_plain_page_text(new.staff_label);
  if cardinality(new.required_review_dimensions) <>
    (select count(distinct dimension) from unnest(new.required_review_dimensions) dimension) then
    raise exception 'Registered reviews must be unique' using errcode = '22023';
  end if;

  for field_definition in select value from jsonb_array_elements(new.field_contract)
  loop
    if jsonb_typeof(field_definition) <> 'object'
      or not field_definition ?& array['key', 'label', 'kind']::text[]
      or exists (
        select 1 from jsonb_object_keys(field_definition) actual(name)
        where actual.name <> all(array[
          'key', 'label', 'kind', 'required', 'maxLength', 'maxItems', 'group', 'helpText'
        ]::text[])
      ) then
      raise exception 'Registered page field contract is not allowed' using errcode = '22023';
    end if;
    field_key := field_definition ->> 'key';
    field_kind := field_definition ->> 'kind';
    if field_key !~ '^[a-z][a-zA-Z0-9_]{0,99}$'
      or field_kind not in ('short', 'long', 'url', 'string-list', 'link-list', 'rich-blocks')
      or jsonb_typeof(field_definition -> 'label') <> 'string'
      or (field_definition ? 'required' and jsonb_typeof(field_definition -> 'required') <> 'boolean')
      or (field_definition ? 'maxLength' and (
        jsonb_typeof(field_definition -> 'maxLength') <> 'number'
        or (field_definition ->> 'maxLength')::integer not between 1 and 100000
      ))
      or (
        field_definition ? 'maxItems' and (
          jsonb_typeof(field_definition -> 'maxItems') <> 'number'
          or (field_definition ->> 'maxItems')::integer not between 1 and 500
        )
      ) then
      raise exception 'Registered page field contract is not allowed' using errcode = '22023';
    end if;
    if field_key = any(keys) then
      raise exception 'Registered page field keys must be unique' using errcode = '22023';
    end if;
    keys := array_append(keys, field_key);
    perform pac.assert_plain_page_text(field_definition ->> 'label');
    if field_definition ? 'group' then perform pac.assert_plain_page_text(field_definition ->> 'group'); end if;
    if field_definition ? 'helpText' then perform pac.assert_plain_page_text(field_definition ->> 'helpText'); end if;
  end loop;

  foreach protected_key in array new.protected_fields
  loop
    if protected_key !~ '^[a-z][a-zA-Z0-9_]{0,99}$' or protected_key = any(keys) then
      raise exception 'Protected fields cannot be editable' using errcode = '22023';
    end if;
  end loop;
  if cardinality(new.protected_fields) <>
    (select count(distinct protected) from unnest(new.protected_fields) protected) then
    raise exception 'Protected page fields must be unique' using errcode = '22023';
  end if;
  return new;
end;
$$;

drop trigger if exists surface_definitions_contract on pac.surface_definitions;
create trigger surface_definitions_contract
before insert or update on pac.surface_definitions
for each row execute function pac.enforce_surface_definition_contract();

create or replace function pac.enforce_surface_revision_contract()
returns trigger
language plpgsql
set search_path = pg_catalog, pac
as $$
declare
  definition pac.surface_definitions%rowtype;
  base_revision pac.surface_revisions%rowtype;
begin
  select * into strict definition from pac.surface_definitions
  where surface_id = new.surface_id and active = true;
  if new.required_review_dimensions is distinct from definition.required_review_dimensions then
    raise exception 'Revision review requirements do not match the registered page area' using errcode = '22023';
  end if;
  perform pac.assert_valid_surface_document(new.surface_id, new.scope_id, new.document);
  if new.based_on_revision_id is not null then
    select * into base_revision from pac.surface_revisions where revision_id = new.based_on_revision_id;
    if not found or base_revision.surface_id <> new.surface_id then
      raise exception 'Revision base does not belong to this page area' using errcode = '22023';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists surface_revisions_contract on pac.surface_revisions;
create trigger surface_revisions_contract
before insert on pac.surface_revisions
for each row execute function pac.enforce_surface_revision_contract();

create or replace function pac.enforce_surface_publication_gate()
returns trigger
language plpgsql
set search_path = pg_catalog, pac
as $$
declare
  definition pac.surface_definitions%rowtype;
  revision pac.surface_revisions%rowtype;
begin
  select * into strict definition from pac.surface_definitions
  where surface_id = new.surface_id and active = true;
  if new.decision = 'inherit' and definition.scope_policy <> 'inheritable' then
    raise exception 'This page area does not permit inherited wording' using errcode = '42501';
  end if;
  if new.revision_id is not null then
    select * into revision from pac.surface_revisions where revision_id = new.revision_id;
    if not found or revision.surface_id <> new.surface_id then
      raise exception 'Publishing decision revision does not belong to this page area' using errcode = '22023';
    end if;
    if new.decision = 'publish' and revision.scope_id <> new.scope_id then
      raise exception 'Published wording must belong to the exact program scope' using errcode = '22023';
    end if;
    if new.decision = 'withdraw' and revision.scope_id <> new.scope_id
      and not (definition.scope_policy = 'inheritable' and new.scope_id = 'dsd' and revision.scope_id = 'one-dhs') then
      raise exception 'Withdrawn wording must be visible in the requested program scope' using errcode = '22023';
    end if;
  end if;
  if new.decision = 'publish' and exists (
    select 1 from unnest(revision.required_review_dimensions) required(dimension)
    left join lateral (
      select review.status from pac.surface_reviews review
      where review.revision_id = revision.revision_id and review.dimension = required.dimension
      order by review.recorded_at desc, review.review_id desc limit 1
    ) current_review on true
    where current_review.status is null or current_review.status not in ('pass', 'not_applicable')
  ) then
    raise exception 'Every required review must be complete before publishing' using errcode = '55000';
  end if;
  if length(btrim(new.reason)) = 0 or length(new.reason) > 1000 then
    raise exception 'A brief publishing reason is required' using errcode = '22023';
  end if;
  perform pac.assert_plain_page_text(new.reason);
  return new;
end;
$$;

drop trigger if exists surface_publication_gate on pac.surface_publication_decisions;
create trigger surface_publication_gate
before insert on pac.surface_publication_decisions
for each row execute function pac.enforce_surface_publication_gate();

create or replace function pac.read_surface_publication(
  requested_scope_id text,
  requested_surface_id text
)
returns table (
  surface_id text,
  revision_id uuid,
  scope_id text,
  document jsonb,
  publication_decision_id bigint,
  decided_at timestamptz
)
language plpgsql
stable
security definer
set search_path = pg_catalog, pac
set row_security = off
as $$
declare
  definition pac.surface_definitions%rowtype;
  local_decision pac.surface_publication_decisions%rowtype;
  selected_decision pac.surface_publication_decisions%rowtype;
begin
  perform pac.assert_surface_request(requested_scope_id, requested_surface_id, false);
  select * into strict definition from pac.surface_definitions
  where surface_definitions.surface_id = requested_surface_id and active = true;

  if requested_scope_id = 'dsd' and definition.scope_policy = 'inheritable' then
    select * into local_decision
    from pac.surface_publication_decisions decision_record
    where decision_record.surface_id = requested_surface_id and decision_record.scope_id = 'dsd'
    order by publication_decision_id desc limit 1;
    if found and local_decision.decision = 'withdraw' then
      return;
    elsif found and local_decision.decision = 'publish' then
      selected_decision := local_decision;
    else
      select * into selected_decision
      from pac.surface_publication_decisions decision_record
      where decision_record.surface_id = requested_surface_id and decision_record.scope_id = 'one-dhs'
      order by publication_decision_id desc limit 1;
    end if;
  elsif definition.scope_policy = 'dsd' then
    select * into selected_decision
    from pac.surface_publication_decisions decision_record
    where decision_record.surface_id = requested_surface_id and decision_record.scope_id = 'dsd'
    order by publication_decision_id desc limit 1;
  else
    select * into selected_decision
    from pac.surface_publication_decisions decision_record
    where decision_record.surface_id = requested_surface_id and decision_record.scope_id = 'one-dhs'
    order by publication_decision_id desc limit 1;
  end if;

  if selected_decision.publication_decision_id is null or selected_decision.decision <> 'publish' then
    return;
  end if;
  return query
  select revision.surface_id, revision.revision_id, revision.scope_id,
    revision.document, selected_decision.publication_decision_id,
    selected_decision.decided_at
  from pac.surface_revisions revision
  where revision.revision_id = selected_decision.revision_id
    and revision.surface_id = requested_surface_id
    and revision.scope_id = selected_decision.scope_id;
end;
$$;

create or replace function pac.read_surface_editing_state(
  requested_scope_id text,
  requested_surface_id text
)
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, pac
set row_security = off
as $$
declare
  definition pac.surface_definitions%rowtype;
  latest_decision pac.surface_publication_decisions%rowtype;
  effective_publication record;
  working_revision pac.surface_revisions%rowtype;
  expected_revision_id uuid;
  ignored_through integer := 0;
  draft_revision_id uuid;
  reviews jsonb := '[]'::jsonb;
  history jsonb := '[]'::jsonb;
  ready_to_publish boolean := false;
begin
  perform pac.assert_surface_request(requested_scope_id, requested_surface_id, true);
  select * into strict definition from pac.surface_definitions
  where surface_id = requested_surface_id and active = true;

  select * into latest_decision
  from pac.surface_publication_decisions decision_record
  where decision_record.surface_id = requested_surface_id
    and decision_record.scope_id = requested_scope_id
  order by publication_decision_id desc limit 1;
  if latest_decision.decision = 'inherit' then
    ignored_through := coalesce((latest_decision.gate_snapshot ->> 'ignoreThroughRevisionNumber')::integer, 0);
  end if;

  select * into working_revision
  from pac.surface_revisions revision
  where revision.surface_id = requested_surface_id
    and revision.scope_id = requested_scope_id
    and revision.revision_number > ignored_through
  order by revision.revision_number desc, revision.revision_id desc limit 1;

  select publication.* into effective_publication
  from pac.read_surface_publication(requested_scope_id, requested_surface_id) publication;

  if working_revision.revision_id is not null and not exists (
    select 1 from pac.surface_publication_decisions decision_record
    where decision_record.surface_id = requested_surface_id
      and decision_record.scope_id = requested_scope_id
      and decision_record.revision_id = working_revision.revision_id
      and decision_record.decision = 'publish'
  ) then
    draft_revision_id := working_revision.revision_id;
  end if;

  if draft_revision_id is not null then
    expected_revision_id := draft_revision_id;
  elsif effective_publication.revision_id is not null then
    expected_revision_id := effective_publication.revision_id;
  elsif latest_decision.decision = 'withdraw' then
    expected_revision_id := latest_decision.revision_id;
  end if;

  if draft_revision_id is not null then
    select coalesce(jsonb_agg(jsonb_build_object(
      'reviewId', current_review.review_id,
      'dimension', required.dimension,
      'status', coalesce(current_review.status, 'pending'),
      'note', current_review.note,
      'recordedAt', current_review.recorded_at
    ) order by array_position(working_revision.required_review_dimensions, required.dimension)), '[]'::jsonb)
    into reviews
    from unnest(working_revision.required_review_dimensions) required(dimension)
    left join lateral (
      select review.review_id, review.status, review.note, review.recorded_at
      from pac.surface_reviews review
      where review.revision_id = draft_revision_id and review.dimension = required.dimension
      order by review.recorded_at desc, review.review_id desc limit 1
    ) current_review on true;

    ready_to_publish := not exists (
      select 1
      from unnest(working_revision.required_review_dimensions) required(dimension)
      left join lateral (
        select review.status from pac.surface_reviews review
        where review.revision_id = draft_revision_id and review.dimension = required.dimension
        order by review.recorded_at desc, review.review_id desc limit 1
      ) current_review on true
      where current_review.status is null or current_review.status not in ('pass', 'not_applicable')
    );
  end if;

  select coalesce(jsonb_agg(entry order by (entry ->> 'revisionNumber')::integer desc), '[]'::jsonb)
  into history
  from (
    select jsonb_build_object(
      'revisionId', revision.revision_id,
      'revisionNumber', revision.revision_number,
      'scope', revision.scope_id,
      'changeNote', revision.change_note,
      'createdAt', revision.created_at,
      'wasPublished', exists (
        select 1 from pac.surface_publication_decisions decision_record
        where decision_record.surface_id = requested_surface_id
          and decision_record.scope_id = requested_scope_id
          and decision_record.revision_id = revision.revision_id
          and decision_record.decision = 'publish'
      ),
      'isEffective', coalesce(revision.revision_id = effective_publication.revision_id, false),
      'isDraft', coalesce(revision.revision_id = draft_revision_id, false),
      'canRestore', revision.revision_id is distinct from effective_publication.revision_id and exists (
        select 1 from pac.surface_publication_decisions decision_record
        where decision_record.surface_id = requested_surface_id
          and decision_record.scope_id = requested_scope_id
          and decision_record.revision_id = revision.revision_id
          and decision_record.decision = 'publish'
      )
    ) as entry
    from pac.surface_revisions revision
    where revision.surface_id = requested_surface_id and revision.scope_id = requested_scope_id
    order by revision.revision_number desc
    limit 100
  ) recent;

  return jsonb_build_object(
    'surfaceId', requested_surface_id,
    'scope', requested_scope_id,
    'expectedRevisionId', expected_revision_id,
    'effective', case when effective_publication.revision_id is null then null else jsonb_build_object(
      'revisionId', effective_publication.revision_id,
      'sourceScope', effective_publication.scope_id,
      'publicationDecisionId', effective_publication.publication_decision_id::text,
      'decidedAt', effective_publication.decided_at,
      'document', effective_publication.document
    ) end,
    'draft', case when draft_revision_id is null then null else jsonb_build_object(
      'revisionId', working_revision.revision_id,
      'revisionNumber', working_revision.revision_number,
      'basedOnRevisionId', working_revision.based_on_revision_id,
      'document', working_revision.document,
      'changeNote', working_revision.change_note,
      'createdAt', working_revision.created_at,
      'reviews', reviews,
      'canPublish', ready_to_publish
    ) end,
    'latestDecision', case when latest_decision.publication_decision_id is null then null else jsonb_build_object(
      'publicationDecisionId', latest_decision.publication_decision_id::text,
      'decision', latest_decision.decision,
      'revisionId', latest_decision.revision_id,
      'reason', latest_decision.reason,
      'decidedAt', latest_decision.decided_at
    ) end,
    'inheritedFrom', case
      when requested_scope_id = 'dsd' and effective_publication.scope_id = 'one-dhs' then 'one-dhs'
      else null
    end,
    'hasUnpublishedChanges', draft_revision_id is not null,
    'history', history
  );
end;
$$;

create or replace function pac.create_surface_draft(
  requested_scope_id text,
  requested_surface_id text,
  expected_base_revision_id uuid,
  requested_document jsonb,
  requested_change_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pac
set row_security = off
as $$
declare
  definition pac.surface_definitions%rowtype;
  current_state jsonb;
  current_base_revision_id uuid;
  current_base_document jsonb;
  next_revision_id uuid;
  next_revision_number integer;
begin
  perform pac.assert_valid_surface_document(requested_surface_id, requested_scope_id, requested_document);
  if requested_change_note is not null and length(btrim(requested_change_note)) > 1000 then
    raise exception 'The change note is too long' using errcode = '22023';
  end if;
  if length(btrim(coalesce(requested_change_note, ''))) > 0 then
    perform pac.assert_plain_page_text(requested_change_note);
  end if;

  perform pg_advisory_xact_lock(hashtextextended(requested_surface_id || ':' || requested_scope_id, 0));
  select * into strict definition from pac.surface_definitions
  where surface_id = requested_surface_id and active = true;
  current_state := pac.read_surface_editing_state(requested_scope_id, requested_surface_id);
  current_base_revision_id := nullif(current_state ->> 'expectedRevisionId', '')::uuid;
  if current_base_revision_id is distinct from expected_base_revision_id then
    raise exception 'Page wording changed after it was opened' using errcode = '40001';
  end if;
  if current_base_revision_id is not null then
    select revision.document into current_base_document
    from pac.surface_revisions revision where revision.revision_id = current_base_revision_id;
  end if;
  if current_base_document = requested_document then
    raise exception 'No page wording changes were provided' using errcode = '22000';
  end if;

  select coalesce(max(revision.revision_number), 0) + 1 into next_revision_number
  from pac.surface_revisions revision
  where revision.surface_id = requested_surface_id and revision.scope_id = requested_scope_id;

  insert into pac.surface_revisions (
    surface_id, scope_id, revision_number, document, change_note,
    required_review_dimensions, created_by, based_on_revision_id
  ) values (
    requested_surface_id, requested_scope_id, next_revision_number, requested_document,
    coalesce(nullif(btrim(requested_change_note), ''), 'Wording updated in the Consultant Workspace.'),
    definition.required_review_dimensions, 'pac-consultant-workspace-owner', current_base_revision_id
  ) returning revision_id into next_revision_id;

  insert into pac.surface_reviews (
    revision_id, dimension, status, note, reviewer_role, reviewer_id
  ) select next_revision_id, dimension, 'pending',
    'Review is required before this wording can be published.',
    'program_steward', 'pac-consultant-workspace-owner'
  from unnest(definition.required_review_dimensions) dimension;

  insert into pac.surface_change_events (
    surface_id, scope_id, revision_id, action, detail, actor_id, actor_role
  ) values (
    requested_surface_id, requested_scope_id, next_revision_id, 'draft_created',
    jsonb_build_object('basedOnRevisionId', current_base_revision_id, 'staffPublicationUnchanged', true),
    'pac-consultant-workspace-owner', 'owner'
  );
  return pac.read_surface_editing_state(requested_scope_id, requested_surface_id);
end;
$$;

create or replace function pac.record_surface_review(
  requested_scope_id text,
  requested_surface_id text,
  requested_revision_id uuid,
  requested_dimension text,
  requested_status text,
  expected_previous_review_id uuid,
  requested_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pac
set row_security = off
as $$
declare
  current_state jsonb;
  previous_review_id uuid;
  required_dimensions text[];
begin
  perform pac.assert_surface_request(requested_scope_id, requested_surface_id, true);
  if requested_status not in ('pass', 'revise', 'blocked', 'not_applicable') then
    raise exception 'Review result is not allowed' using errcode = '22023';
  end if;
  if requested_note is not null and length(btrim(requested_note)) > 1000 then
    raise exception 'The review note is too long' using errcode = '22023';
  end if;
  if length(btrim(coalesce(requested_note, ''))) > 0 then
    perform pac.assert_plain_page_text(requested_note);
  end if;

  perform pg_advisory_xact_lock(hashtextextended(requested_surface_id || ':' || requested_scope_id, 0));
  current_state := pac.read_surface_editing_state(requested_scope_id, requested_surface_id);
  if current_state #>> '{draft,revisionId}' is null
    or (current_state #>> '{draft,revisionId}')::uuid is distinct from requested_revision_id then
    raise exception 'Only the current draft can be reviewed' using errcode = '40001';
  end if;
  select revision.required_review_dimensions into required_dimensions
  from pac.surface_revisions revision
  where revision.revision_id = requested_revision_id
    and revision.surface_id = requested_surface_id and revision.scope_id = requested_scope_id;
  if not found or requested_dimension <> all(required_dimensions) then
    raise exception 'This review area is not required' using errcode = '22023';
  end if;

  select review.review_id into previous_review_id
  from pac.surface_reviews review
  where review.revision_id = requested_revision_id and review.dimension = requested_dimension
  order by review.recorded_at desc, review.review_id desc limit 1;
  if previous_review_id is distinct from expected_previous_review_id then
    raise exception 'This review changed after it was opened' using errcode = '40001';
  end if;

  insert into pac.surface_reviews (
    revision_id, dimension, status, note, reviewer_role, reviewer_id, supersedes_review_id
  ) values (
    requested_revision_id, requested_dimension, requested_status,
    nullif(btrim(requested_note), ''), 'program_steward',
    'pac-consultant-workspace-owner', previous_review_id
  );
  insert into pac.surface_change_events (
    surface_id, scope_id, revision_id, action, detail, actor_id, actor_role
  ) values (
    requested_surface_id, requested_scope_id, requested_revision_id, 'review_recorded',
    jsonb_build_object('dimension', requested_dimension, 'status', requested_status),
    'pac-consultant-workspace-owner', 'owner'
  );
  return pac.read_surface_editing_state(requested_scope_id, requested_surface_id);
end;
$$;

create or replace function pac.publish_surface_draft(
  requested_scope_id text,
  requested_surface_id text,
  requested_revision_id uuid,
  expected_publication_decision_id bigint,
  requested_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pac
set row_security = off
as $$
declare
  current_state jsonb;
  current_decision_id bigint;
  draft_revision pac.surface_revisions%rowtype;
  gate_reviews jsonb;
  next_decision_id bigint;
begin
  perform pac.assert_surface_request(requested_scope_id, requested_surface_id, true);
  if requested_reason is null or length(btrim(requested_reason)) not between 1 and 1000 then
    raise exception 'A brief publishing reason is required' using errcode = '22023';
  end if;
  perform pac.assert_plain_page_text(requested_reason);
  perform pg_advisory_xact_lock(hashtextextended(requested_surface_id || ':' || requested_scope_id, 0));

  select publication_decision_id into current_decision_id
  from pac.surface_publication_decisions decision_record
  where decision_record.surface_id = requested_surface_id and decision_record.scope_id = requested_scope_id
  order by publication_decision_id desc limit 1;
  if current_decision_id is distinct from expected_publication_decision_id then
    raise exception 'The publication decision changed after it was opened' using errcode = '40001';
  end if;
  current_state := pac.read_surface_editing_state(requested_scope_id, requested_surface_id);
  if current_state #>> '{draft,revisionId}' is null
    or (current_state #>> '{draft,revisionId}')::uuid is distinct from requested_revision_id then
    raise exception 'Only the current draft can be published' using errcode = '40001';
  end if;
  select * into strict draft_revision from pac.surface_revisions revision
  where revision.revision_id = requested_revision_id
    and revision.surface_id = requested_surface_id and revision.scope_id = requested_scope_id;
  perform pac.assert_valid_surface_document(requested_surface_id, requested_scope_id, draft_revision.document);
  if exists (
    select 1 from unnest(draft_revision.required_review_dimensions) required(dimension)
    left join lateral (
      select review.status from pac.surface_reviews review
      where review.revision_id = requested_revision_id and review.dimension = required.dimension
      order by review.recorded_at desc, review.review_id desc limit 1
    ) current_review on true
    where current_review.status is null or current_review.status not in ('pass', 'not_applicable')
  ) then
    raise exception 'Every required review must be complete before publishing' using errcode = '55000';
  end if;
  select jsonb_agg(jsonb_build_object(
    'dimension', required.dimension, 'status', current_review.status,
    'reviewId', current_review.review_id
  ) order by array_position(draft_revision.required_review_dimensions, required.dimension))
  into gate_reviews
  from unnest(draft_revision.required_review_dimensions) required(dimension)
  cross join lateral (
    select review.review_id, review.status from pac.surface_reviews review
    where review.revision_id = requested_revision_id and review.dimension = required.dimension
    order by review.recorded_at desc, review.review_id desc limit 1
  ) current_review;

  insert into pac.surface_publication_decisions (
    surface_id, scope_id, revision_id, decision, gate_snapshot, reason, decided_by
  ) values (
    requested_surface_id, requested_scope_id, requested_revision_id, 'publish',
    jsonb_build_object(
      'requiredReviews', gate_reviews, 'requiredReviewsComplete', true,
      'registeredFieldsChecked', true, 'staffLanguageChecked', true,
      'plainTextChecked', true, 'iconsChecked', true,
      'explicitOwnerDecision', true, 'replacedScopeDecisionId', current_decision_id
    ), btrim(requested_reason), 'pac-consultant-workspace-owner'
  ) returning publication_decision_id into next_decision_id;
  insert into pac.surface_change_events (
    surface_id, scope_id, revision_id, publication_decision_id, action, detail, actor_id, actor_role
  ) values (
    requested_surface_id, requested_scope_id, requested_revision_id, next_decision_id,
    'published', jsonb_build_object('staffCopyChanged', true),
    'pac-consultant-workspace-owner', 'owner'
  );
  return pac.read_surface_editing_state(requested_scope_id, requested_surface_id);
end;
$$;

create or replace function pac.withdraw_surface_publication(
  requested_scope_id text,
  requested_surface_id text,
  expected_published_revision_id uuid,
  expected_publication_decision_id bigint,
  requested_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pac
set row_security = off
as $$
declare
  current_decision_id bigint;
  effective_publication record;
  next_decision_id bigint;
begin
  perform pac.assert_surface_request(requested_scope_id, requested_surface_id, true);
  if requested_reason is null or length(btrim(requested_reason)) not between 1 and 1000 then
    raise exception 'A brief withdrawal reason is required' using errcode = '22023';
  end if;
  perform pac.assert_plain_page_text(requested_reason);
  perform pg_advisory_xact_lock(hashtextextended(requested_surface_id || ':' || requested_scope_id, 0));
  select publication_decision_id into current_decision_id
  from pac.surface_publication_decisions decision_record
  where decision_record.surface_id = requested_surface_id and decision_record.scope_id = requested_scope_id
  order by publication_decision_id desc limit 1;
  if current_decision_id is distinct from expected_publication_decision_id then
    raise exception 'The publication decision changed after it was opened' using errcode = '40001';
  end if;
  select publication.* into effective_publication
  from pac.read_surface_publication(requested_scope_id, requested_surface_id) publication;
  if effective_publication.revision_id is null
    or effective_publication.revision_id is distinct from expected_published_revision_id then
    raise exception 'Published wording changed after it was opened' using errcode = '40001';
  end if;

  insert into pac.surface_publication_decisions (
    surface_id, scope_id, revision_id, decision, gate_snapshot, reason, decided_by
  ) values (
    requested_surface_id, requested_scope_id, effective_publication.revision_id, 'withdraw',
    jsonb_build_object(
      'explicitOwnerDecision', true, 'replacedScopeDecisionId', current_decision_id,
      'withdrawnEffectiveSourceScope', effective_publication.scope_id
    ), btrim(requested_reason), 'pac-consultant-workspace-owner'
  ) returning publication_decision_id into next_decision_id;
  insert into pac.surface_change_events (
    surface_id, scope_id, revision_id, publication_decision_id, action, detail, actor_id, actor_role
  ) values (
    requested_surface_id, requested_scope_id, effective_publication.revision_id,
    next_decision_id, 'withdrawn', jsonb_build_object('staffCopyChanged', true),
    'pac-consultant-workspace-owner', 'owner'
  );
  return pac.read_surface_editing_state(requested_scope_id, requested_surface_id);
end;
$$;

create or replace function pac.resume_surface_inheritance(
  requested_scope_id text,
  requested_surface_id text,
  expected_publication_decision_id bigint,
  requested_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pac
set row_security = off
as $$
declare
  definition pac.surface_definitions%rowtype;
  current_decision pac.surface_publication_decisions%rowtype;
  ignored_through integer;
  next_decision_id bigint;
begin
  perform pac.assert_surface_request(requested_scope_id, requested_surface_id, true);
  select * into strict definition from pac.surface_definitions
  where surface_id = requested_surface_id and active = true;
  if requested_scope_id <> 'dsd' or definition.scope_policy <> 'inheritable' then
    raise exception 'This page area cannot resume One DHS inheritance' using errcode = '42501';
  end if;
  if requested_reason is null or length(btrim(requested_reason)) not between 1 and 1000 then
    raise exception 'A brief inheritance reason is required' using errcode = '22023';
  end if;
  perform pac.assert_plain_page_text(requested_reason);
  perform pg_advisory_xact_lock(hashtextextended(requested_surface_id || ':' || requested_scope_id, 0));
  select * into current_decision
  from pac.surface_publication_decisions decision_record
  where decision_record.surface_id = requested_surface_id and decision_record.scope_id = 'dsd'
  order by publication_decision_id desc limit 1;
  if current_decision.publication_decision_id is distinct from expected_publication_decision_id then
    raise exception 'The publication decision changed after it was opened' using errcode = '40001';
  end if;
  if current_decision.publication_decision_id is null or current_decision.decision = 'inherit' then
    raise exception 'This page area already follows One DHS wording' using errcode = '22000';
  end if;
  select coalesce(max(revision_number), 0) into ignored_through
  from pac.surface_revisions revision
  where revision.surface_id = requested_surface_id and revision.scope_id = 'dsd';
  insert into pac.surface_publication_decisions (
    surface_id, scope_id, revision_id, decision, gate_snapshot, reason, decided_by
  ) values (
    requested_surface_id, 'dsd', null, 'inherit',
    jsonb_build_object(
      'explicitOwnerDecision', true, 'replacedScopeDecisionId', current_decision.publication_decision_id,
      'ignoreThroughRevisionNumber', ignored_through
    ), btrim(requested_reason), 'pac-consultant-workspace-owner'
  ) returning publication_decision_id into next_decision_id;
  insert into pac.surface_change_events (
    surface_id, scope_id, publication_decision_id, action, detail, actor_id, actor_role
  ) values (
    requested_surface_id, 'dsd', next_decision_id, 'inheritance_resumed',
    jsonb_build_object('ignoredThroughRevisionNumber', ignored_through),
    'pac-consultant-workspace-owner', 'owner'
  );
  return pac.read_surface_editing_state('dsd', requested_surface_id);
end;
$$;

create or replace function pac.restore_surface_revision(
  requested_scope_id text,
  requested_surface_id text,
  target_revision_id uuid,
  expected_publication_decision_id bigint,
  requested_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, pac
set row_security = off
as $$
declare
  current_decision_id bigint;
  target_revision pac.surface_revisions%rowtype;
  effective_publication record;
  previous_publish_id bigint;
  next_decision_id bigint;
begin
  perform pac.assert_surface_request(requested_scope_id, requested_surface_id, true);
  if requested_reason is null or length(btrim(requested_reason)) not between 1 and 1000 then
    raise exception 'A brief restoration reason is required' using errcode = '22023';
  end if;
  perform pac.assert_plain_page_text(requested_reason);
  perform pg_advisory_xact_lock(hashtextextended(requested_surface_id || ':' || requested_scope_id, 0));
  select publication_decision_id into current_decision_id
  from pac.surface_publication_decisions decision_record
  where decision_record.surface_id = requested_surface_id and decision_record.scope_id = requested_scope_id
  order by publication_decision_id desc limit 1;
  if current_decision_id is distinct from expected_publication_decision_id then
    raise exception 'The publication decision changed after it was opened' using errcode = '40001';
  end if;
  select * into target_revision from pac.surface_revisions revision
  where revision.revision_id = target_revision_id
    and revision.surface_id = requested_surface_id and revision.scope_id = requested_scope_id;
  if not found then
    raise exception 'The selected approved wording is not available' using errcode = 'P0002';
  end if;
  select publication_decision_id into previous_publish_id
  from pac.surface_publication_decisions decision_record
  where decision_record.surface_id = requested_surface_id
    and decision_record.scope_id = requested_scope_id
    and decision_record.revision_id = target_revision_id
    and decision_record.decision = 'publish'
  order by publication_decision_id desc limit 1;
  if previous_publish_id is null then
    raise exception 'Only previously approved wording can be restored' using errcode = '55000';
  end if;
  perform pac.assert_valid_surface_document(requested_surface_id, requested_scope_id, target_revision.document);
  select publication.* into effective_publication
  from pac.read_surface_publication(requested_scope_id, requested_surface_id) publication;
  if effective_publication.revision_id is not distinct from target_revision_id then
    raise exception 'The selected wording is already available to staff' using errcode = '22000';
  end if;

  insert into pac.surface_publication_decisions (
    surface_id, scope_id, revision_id, decision, gate_snapshot, reason, decided_by
  ) values (
    requested_surface_id, requested_scope_id, target_revision_id, 'publish',
    jsonb_build_object(
      'explicitOwnerDecision', true, 'restoredApprovedRevision', true,
      'previousPublishDecisionId', previous_publish_id,
      'replacedScopeDecisionId', current_decision_id,
      'registeredFieldsChecked', true, 'staffLanguageChecked', true,
      'plainTextChecked', true, 'iconsChecked', true
    ), btrim(requested_reason), 'pac-consultant-workspace-owner'
  ) returning publication_decision_id into next_decision_id;
  insert into pac.surface_change_events (
    surface_id, scope_id, revision_id, publication_decision_id, action, detail, actor_id, actor_role
  ) values (
    requested_surface_id, requested_scope_id, target_revision_id, next_decision_id,
    'restored', jsonb_build_object('previousPublishDecisionId', previous_publish_id),
    'pac-consultant-workspace-owner', 'owner'
  );
  return pac.read_surface_editing_state(requested_scope_id, requested_surface_id);
end;
$$;

