uired":true,"maxLength":2000}],"protectedFields":[],"requiredReviewDimensions":["language_alignment","factual_currentness","accessibility","scope","placement"],"approvedValues":{"introKicker":"Begin with the work in front of you","introTitle":"Where would you like to start?","introLede":"Choose your role, the kind of work you are doing, and when you need to act. The program will suggest a useful place to begin and explain why.","formKicker":"Three short choices","formTitle":"Tell us where the work sits","formIntro":"Choose the closest answer. You can explore a different route at any time.","roleLabel":"What role are you bringing to this work?","rolePlaceholder":"Choose a role","taskLabel":"What kind of work are you doing?","taskPlaceholder":"Choose an area of work","urgencyLabel":"When do you need to act?","submitLabel":"Show a place to start","resultKicker":"Your route","emptyResultTitle":"A practical next step will appear here","emptyResultBody":"Your choices are used only to suggest a route on this page. They are not saved, scored, or sent to a supervisor.","recommendationPrefix":"Start with","workHeading":"Work you can begin","areaLinkLabel":"Explore this area","practiceLinkLabel":"Create a work product","supportLinkLabel":"Find human support","roleStaffMemberLabel":"Staff member","roleStaffMemberGuidance":"Use the examples and tools closest to the work you are doing.","roleSupervisorOrManagerLabel":"Supervisor or manager","roleSupervisorOrManagerGuidance":"Consider both the decision and how staff and communities will experience it.","rolePolicyProgramOrServiceProfessionalLabel":"Policy, program, or service professional","rolePolicyProgramOrServiceProfessionalGuidance":"Bring equity and access into the work while there is still room to shape it.","roleWorkforceOrHumanResourcesProfessionalLabel":"Workforce or Human Resources professional","roleWorkforceOrHumanResourcesProfessionalGuidance":"Look across the employee experience, including barriers that may not be v