 guidance","kind":"long","required":true,"maxLength":4000},{"key":"step0Links","label":"Step 1: links","kind":"link-list","required":false,"maxLength":500},{"key":"step1Title","label":"Step 2: heading","kind":"short","required":true,"maxLength":300},{"key":"step1Guidance","label":"Step 2: guidance","kind":"long","required":true,"maxLength":4000},{"key":"step1Links","label":"Step 2: links","kind":"link-list","required":false,"maxLength":500},{"key":"step2Title","label":"Step 3: heading","kind":"short","required":true,"maxLength":300},{"key":"step2Guidance","label":"Step 3: guidance","kind":"long","required":true,"maxLength":4000},{"key":"step2Links","label":"Step 3: links","kind":"link-list","required":false,"maxLength":500},{"key":"step3Title","label":"Step 4: heading","kind":"short","required":true,"maxLength":300},{"key":"step3Guidance","label":"Step 4: guidance","kind":"long","required":true,"maxLength":4000},{"key":"step3Links","label":"Step 4: links","kind":"link-list","required":false,"maxLength":500},{"key":"step4Title","label":"Step 5: heading","kind":"short","required":true,"maxLength":300},{"key":"step4Guidance","label":"Step 5: guidance","kind":"long","required":true,"maxLength":4000},{"key":"step4Links","label":"Step 5: links","kind":"link-list","required":false,"maxLength":500},{"key":"step5Title","label":"Step 6: heading","kind":"short","required":true,"maxLength":300},{"key":"step5Guidance","label":"Step 6: guidance","kind":"long","required":true,"maxLength":4000},{"key":"step5Links","label":"Step 6: links","kind":"link-list","required":false,"maxLength":500},{"key":"artifactField0Label","label":"Working-notes field 1: label","kind":"short","required":true,"maxLength":300},{"key":"artifactField0Help","label":"Working-notes field 1: help","kind":"long","required":false,"maxLength":4000},{"key":"artifactField1Label","label":"Working-notes field 2: label","kind":"short","required":true,"maxLength":300},{"key":"artifactField1Help","label":"Working-notes f