ength":4000},{"key":"whyItMatters","label":"Why it matters for DHS work","kind":"long","required":true,"maxLength":4000},{"key":"withinGroupDiversity","label":"Differences within the community","kind":"long","required":true,"maxLength":4000},{"key":"preferredNames","label":"Preferred names and terms","kind":"string-list","required":true,"maxLength":2000},{"key":"alsoUsedNames","label":"Other names and terms","kind":"string-list","required":false,"maxLength":2000},{"key":"nameNote","label":"Naming guidance","kind":"long","required":true,"maxLength":4000},{"key":"nameUncertainty","label":"What is still unclear","kind":"long","required":false,"maxLength":4000},{"key":"whatToAsk","label":"What to ask","kind":"string-list","required":true,"maxLength":2000},{"key":"accessChecks","label":"Access checks","kind":"string-list","required":true,"maxLength":2000},{"key":"whoToInvolve","label":"Who to involve","kind":"string-list","required":true,"maxLength":2000},{"key":"whatNotToAssume","label":"What not to assume","kind":"string-list","required":true,"maxLength":2000},{"key":"deeper0Heading","label":"Deeper context 1: heading","kind":"short","required":true,"maxLength":300},{"key":"deeper0Body","label":"Deeper context 1: explanation","kind":"long","required":true,"maxLength":4000},{"key":"deeper1Heading","label":"Deeper context 2: heading","kind":"short","required":true,"maxLength":300},{"key":"deeper1Body","label":"Deeper context 2: explanation","kind":"long","required":true,"maxLength":4000},{"key":"deeper2Heading","label":"Deeper context 3: heading","kind":"short","required":true,"maxLength":300},{"key":"deeper2Body","label":"Deeper context 3: explanation","kind":"long","required":true,"maxLength":4000},{"key":"deeper3Heading","label":"Deeper context 4: heading","kind":"short","required":true,"maxLength":300},{"key":"deeper3Body","label":"Deeper context 4: explanation","kind":"long","required":true,"maxLength":4000},{"key":"source0Label","label":"Source 1: name","kind":"short","required":true,"maxLength":300},{"key":"source0Note","label":"Source 1: note","kind":"long","required":true,"maxLength":4000},{"key":"source0Href","label":"Source 1: destination","kind":"url","required":false,"maxLength":2000},{"key":"source1Label","label":"Source 2: name","kind":"short","required":true,"maxLength":300},{"key":"source1Note","label":"Source 2: note","kind":"long","required":true,"maxLength":4000},{"key":"source1Href","label":"Source 2: destination","kind":"url","required":false,"maxLength":2000},{"key":"source2Label","label":"Source 3: name","kind":"short","required":true,"maxLength":300},{"key":"source2Note","label":"Source 3: note","kind":"long","required":true,"maxLength":4000},{"key":"source2Href","label":"Source 3: destination","kind":"url","required":false,"maxLength":2000},{"key":"observance0Title","label":"Observance 1: name","kind":"short","required":true,"maxLength":300},{"key":"observance0When","label":"Observance 1: timing","kind":"short","required":true,"maxLength":300},{"key":"observance0AtWork","label":"Observance 1: workplace guidance","kind":"long","required":true,"maxLength":4000},{"key":"observance1Title","label":"Observance 2: name","kind":"short","required":true,"maxLength":300},{"key":"observance1When","label":"Observance 2: timing","kind":"short","required":true,"maxLength":300},{"key":"observance1AtWork","label":"Observance 2: workplace guidance","kind":"long","required":true,"maxLength":4000}],"protectedFields":["status","reviewDate","representationReview","tribalGate","provenance","relatedPathIds","tags"],"requiredReviewDimensions":["language_alignment","factual_currentness","accessibility","scope","placement","rights_and_consent","community_representation"],"approvedValues":{"title":"Somali Minnesotans","kicker":"Community brief","owner":"Equity and Inclusion Operations Consultant","languages":["Somali (Standard)","Maay","Benadiri","Arabic (religious use)","English (second generation)"],"whoAndWhere":"Minnesota has the largest Somali community in the United States. Families live across the Twin Cities and in Greater Minnesota. Arrival after the 1991 collapse of the Somali state is part of the community's refugee history. DHS staff today also serve a large U.S.-born generation and work with families through disability waivers and child welfare. Counts differ by source, so include the source date with any number you cite.","whyItMatters":"A Somali interpreter who does not speak Maay, a form that cannot accept a three-part name, or an exception process offered only in English can prevent meaningful access. This community's history with public systems also includes times when seeking help led to a child-protection report.","withinGroupDiversity":"The community includes people who are more or less observant, women who lead households, businesses, and finances, young people who have never lived in Somalia, and people who will not discuss clan with an outsider. No one description captures every Somali person or family.","preferredNames":["Somali","Somali Minnesotan","Somali American"],"alsoUsedNames":["Somali-American","East African (umbrella; not a substitute)"],"nameNote":"Naming follows a given name, father's name, and grandfather's name. Many people do not use a family surname the way a database expects one. Do not invent a last name because a field requires it.","nameUncertainty":"Ask how the person wants to be addressed and which name appears on their documents.","whatToAsk":["Which language and dialect should we book: Standard Somali, Maay, or Benadiri?","Would you like a gender-matched interpreter?","Who should be in the room for this decision?","How are your names written on your documents, and how would you like us to address you?","What has already been hard about working with an agency, so we do not repeat it?"],"accessChecks":["Interpreter request names the dialect and any gender-match request.","Vital notices are translated with human review, and exception processes are available to people who do not use English.","Forms accept three-part names; no invented surname.","Timing respects Friday prayer, Ramadan, and Eid where relevant; ask rather than assume observance.","A phone or in-person path exists for people without broadband or comfort with online accounts."],"whoToInvolve":["Language access lead or interpreter services, with the dialect written on the request.","Equity Director for the administration or the person responsible for the program.","Community partner organizations identified in this brief, with a clear purpose, role, compensation, and plan to report back.","Involve community-based Somali organizations and mosques named by the family as partners. Include an imam in case planning only when the family asks.","Do not expect Somali-speaking colleagues to interpret without compensation or to represent the entire community."],"whatNotToAssume":["Do not assume Cedar-Riverside or the metro; Greater Minnesota is part of the map.","Do not ask about clan as an icebreaker or treat it as a risk factor; if the family names it, listen.","Do not assume that a smile, silence, or hospitality is consent to a plan.","Do not fold this household into an African American or Oromo brief because both are Black or East African.","Do not treat religious observance as uniform; ask this family."],"deeper0Heading":"Language access","deeper0Body":"Standard Somali, Maay, and Benadiri may require different interpreters. Arabic is used for religion, and many second-generation people use English. When an exception is available only in English, a household that cannot use English may not be able to access it.","deeper1Heading":"Disability, autism, and public systems","deeper1Body":"Community concern about autism identification in Minneapolis is public. A 2014 Minnesota Department of Health qualitative study with Somali parents described shame and blame, wait lists, English-only meetings, fear of housing loss, and the wish for peers who share a language. Both the fear and the system's dismissals are real. Help-seeking that turned into a child-protection report is part of this history.","deeper2Heading":"Faith and family in daily life","deeper2Body":"Prayer, Ramadan, Eid, halal food, modesty, and honor shape daily life for many families. Elders often speak first; decisions may be family decisions. Civil war and resettlement also put many Somali women in work, business, and household finance. Both can be true in the same room.","deeper3Heading":"History, trust, and public systems","deeper3Body":"Distrust of government after war, camps, and surveillance has a clear history. After public attacks on the community, a DHS badge may not automatically be understood as a sign of help. Mental-health stigma and war trauma may both shape a person's experience. Minnesota writing has described a triple jeopardy: Black, Muslim, and immigrant. Cultural context is incomplete unless it also considers these structural conditions.","source0Label":"Minnesota Compass, Somali cultural community profile","source0Note":"Ancestry counts and geography; include the source date when citing this information.","source0Href":"https://www.mncompass.org/","source1Label":"Minnesota Department of Health, 2014 Somali autism qualitative study","source1Note":"Parent experience with identification and services; verify the current citation.","source1Href":"","source2Label":"Community self-description","source2Note":"Community-informed description is pending source and representation review.","source2Href":"","observance0Title":"Ramadan and Eid al-Fitr","observance0When":"Lunar calendar; dates shift each year","observance0AtWork":"Avoid scheduling required meetings at fast-breaking time; ask before assuming observance.","observance1Title":"Eid al-Adha","observance1When":"Lunar calendar","observance1AtWork":"Ask about availability; do not assume."}},{"surfaceId":"community-brief.hmong","routePattern":"/minnesota-communities/hmong","staffLabel":"Hmong","scopePolicy":"inheritable","fieldContract":[{"key":"title","label":"Brief title","kind":"short","required":true,"maxLength":300},{"key":"kicker","label":"Brief section label","kind":"short","required":true,"maxLength":300},{"key":"owner","label":"Maintainer","kind":"short","required":true,"maxLength":300},{"key":"languages","label":"Languages named in the brief","kind":"string-list","required":true,"maxLength":2000},{"key":"whoAndWhere","label":"Who and where","kind":"long","required":true,"maxLength":4000},{"key":"whyItMatters","label":"Why it matters for DHS work","kind":"long","required":true,"maxLength":4000},{"key":"withinGroupDiversity","label":"Differences within the community","kind":"long","required":true,"maxLength":4000},{"key":"preferredNames","label":"Preferred names and terms","kind":"string-list","required":true,"maxLength":2000},{"key":"alsoUsedNames","label":"Other names and terms","kind":"string-list","required":false,"maxLength":2000},{"key":"nameNote","label":"Naming guidance","kind":"long","required":true,"maxLength":4000},{"key":"nameUncertainty","label":"What is still unclear","kind":"long","required":false,"maxLength":4000},{"key":"whatToAsk","label":"What to ask","kind":"string-list","required":true,"maxLength":2000},{"key":"accessChecks","label":"Access checks","kind":"string-list","required":true,"maxLength":2000},{"key":"whoToInvolve","label":"Who to involve","kind":"string-list","required":true,"maxLength":2000},{"key":"whatNotToAssume","label":"What not to assume","kind":"string-list","required":true,"maxLength":2000},{"key":"deeper0Heading","label":"Deeper context 1: heading","kind":"short","required":true,"maxLength":300},{"key":"deeper0Body","label":"Deeper context 1: explanation","kind":"long","required":true,"maxLength":4000},{"key":"deeper1Heading","label":"Deeper context 2: heading","kind":"short","required":true,"maxLength":300},{"key":"deeper1Body","label":"Deeper context 2: explanation","kind":"long","required":true,"maxLength":4000},{"key":"source0Label","label":"Source 1: name","kind":"short","required":true,"maxLength":300},{"key":"source0Note","label":"Source 1: note","kind":"long","required":true,"maxLength":4000},{"key":"source0Href","label":"Source 1: destination","kind":"url","required":false,"maxLength":2000},{"key":"source1Label","label":"Source 2: name","kind":"short","required":true,"maxLength":300},{"key":"source1Note","label":"Source 2: note","kind":"long","required":true,"maxLength":4000},{"key":"source1Href","label":"Source 2: destination","kind":"url","required":false,"maxLength":2000},{"key":"observance0Title","label":"Observance 1: name","kind":"short","required":true,"maxLength":300},{"key":"observance0When","label":"Observance 1: timing","kind":"short","required":true,"maxLength":300},{"key":"observance0AtWork","label":"Observance 1: workplace guidance","kind":"long","required":true,"maxLength":4000}],"protectedFields":["status","reviewDate","representationReview","tribalGate","provenance","relatedPathIds","tags"],"requiredReviewDimensions":["language_alignment","factual_currentness","accessibility","scope","placement","rights_and_consent","community_representation"],"approvedValues":{"title":"Hmong Minnesotans","kicker":"Community brief","owner":"Equity and Inclusion Operations Consultant","languages":["Hmong (White Hmong, Hmong Daw)","Hmong (Green Hmong, Mong Leng)","English (second and third generation)"],"whoAndWhere":"The United States ran a Secret War in Laos; Hmong forces allied with the CIA. After 1975 came persecution, camps in Thailand, and refugee resettlement. St. Paul is a national hub. Most Hmong Minnesotans live in the Twin Cities; many are second and third generation.","whyItMatters":"A broad 'Asian' category does not provide enough information to meet a person's needs. White Hmong and Green Hmong are not always interchangeable when arranging an interpreter. Clan may shape who speaks and who helps, and Hmong naming practices may not fit forms built around first, middle, and last names.","withinGroupDiversity":"Traditional healing and Christianity are both widespread. Elders and U.S.-born youth may differ sharply on language and family authority. Clan matters for some families and not for others.","preferredNames":["Hmong","Hmong Minnesotan","Hmong American"],"alsoUsedNames":["Mong (used by some Green Hmong speakers)"],"nameNote":"Clan names are shared by many people; given names may change at marriage or with an honorific for men. Ask how the person wants to be addressed.","nameUncertainty":"Spelling of the language name itself (Hmong, Mong) is contested among speakers; follow the person.","whatToAsk":["Which Hmong should we book: White Hmong or Green Hmong?","Who should be in the room for this decision?","Are there traditional healers or church leaders the family wants involved? Do not add them unless named.","How are names written on your documents?"],"accessChecks":["Interpreter request specifies the dialect.","Written Hmong literacy varies; do not assume a translated notice is readable by every household.","Family definitions on forms may miss who actually cares for a child; note the gap.","Timing around Hmong New Year (late fall) and family obligations; ask."],"whoToInvolve":["Language access lead or interpreter services, with the dialect written on the request.","Equity Director for the administration or the person responsible for the program.","Community partner organizations identified in this brief, with a clear purpose, role, compensation, and plan to report back.","Hmong-serving organizations the family names, as partners with purpose and compensation.","Do not expect Hmong-speaking colleagues to teach others about the entire community."],"whatNotToAssume":["Do not assume that nodding or a quiet response means agreement; a person may remain quiet even when a plan does not fit their household.","Do not use clan as an icebreaker or collect it as data.","Do not treat Hmong New Year as Chinese New Year.","Do not assume deportation or profiling anxiety is folklore; it is current structure for some families."],"deeper0Heading":"Healing and disability","deeper0Body":"Traditional healing and shamanism shape what illness means for many families; Christianity is also widespread. Hmong parents of children with autism have described late identification, unclear meaning of the word, stigma, and professionals who were not responsive. Under-identification in one community can exist alongside over-concern in another; both service systems and cultural understandings matter.","deeper1Heading":"Family, ancestors, and respect","deeper1Body":"Family and clan reputation matter. Respect for elders and ancestors is expected. Treat resilience as lived history, not as a slogan.","source0Label":"Minnesota Compass, Hmong cultural community profile","source0Note":"Counts and geography; include the source date when citing this information.","source0Href":"https://www.mncompass.org/","source1Label":"Minnesota Department of Health, 2014 autism qualitative study (Hmong parents)","source1Note":"Verify the current citation.","source1Href":"","observance0Title":"Hmong New Year","observance0When":"Late November to December in St. Paul","observance0AtWork":"Public celebrations; attend respectfully as a guest rather than treating the event as a research opportunity."}},{"surfaceId":"community-brief.karen","routePattern":"/minnesota-communities/karen","staffLabel":"Karen","scopePolicy":"inheritable","fieldContract":[{"key":"title","label":"Brief title","kind":"short","required":true,"maxLength":300},{"key":"kicker","label":"Brief section label","kind":"short","required":true,"maxLength":300},{"key":"owner","label":"Maintainer","kind":"short","required":true,"maxLength":300},{"key":"languages","label":"Languages named in the brief","kind":"string-list","required":true,"maxLength":2000},{"key":"whoAndWhere","label":"Who and where","kind":"long","required":true,"maxLength":4000},{"key":"whyItMatters","label":"Why it matters for DHS work","kind":"long","required":true,"maxLength":4000},{"key":"withinGroupDiversity","label":"Differences within the community","kind":"long","required":true,"maxLength":4000},{"key":"preferredNames","label":"Preferred names and terms","kind":"string-list","required":true,"maxLength":2000},{"key":"alsoUsedNames","label":"Other names and terms","kind":"string-list","required":false,"maxLength":2000},{"key":"nameNote","label":"Naming guidance","kind":"long","required":true,"maxLength":4000},{"key":"nameUncertainty","label":"What is still unclear","kind":"long","required":false,"maxLength":4000},{"key":"whatToAsk","label":"What to ask","kind":"string-list","required":true,"maxLength":2000},{"key":"accessChecks","label":"Access checks","kind":"string-list","required":true,"maxLength":2000},{"key":"whoToInvolve","label":"Who to involve","kind":"string-list","required":true,"maxLength":2000},{"key":"whatNotToAssume","label":"What not to assume","kind":"string-list","required":true,"maxLength":2000},{"key":"source0Label","label":"Source 1: name","kind":"short","required":true,"maxLength":300},{"key":"source0Note","label":"Source 1: note","kind":"long","required":true,"maxLength":4000},{"key":"source0Href","label":"Source 1: destination","kind":"url","required":false,"maxLength":2000}],"protectedFields":["status","reviewDate","representationReview","tribalGate","provenance","relatedPathIds","tags"],"requiredReviewDimensions":["language_alignment","factual_currentness","accessibility","scope","placement","rights_and_consent","community_representation"],"approvedValues":{"title":"Karen Minnesotans","kicker":"Community brief","owner":"Equity and Inclusion Operations Consultant","languages":["S'gaw Karen","Pwo Karen","Burmese","English"],"whoAndWhere":"Karen (Kayin) people from Burma/Myanmar lived through decades of conflict with the Burmese state, long stays in camps in Thailand, and resettlement into the Twin Cities and Greater Minnesota, including southern Minnesota towns.","whyItMatters":"A broad 'Burmese' or 'Asian' category may keep a Karen person from receiving the right support. S'gaw and Pwo may require different interpreters. Services must also reach Karen communities in rural Minnesota, not only St. Paul.","withinGroupDiversity":"Baptist and Buddhist streams both live here. Literacy in the language of the form is not guaranteed.","preferredNames":["Karen"],"alsoUsedNames":["Kayin (official Burmese usage)","Burmese (a national label, not this community)"],"nameNote":"Ask which Karen language the household speaks and how names appear on documents.","nameUncertainty":"","whatToAsk":["S'gaw or Pwo Karen?","Who should be in the room?","Which church or community organization, if any, does the family want involved?","Do you agree with this plan? Please tell me if not."],"accessChecks":["Dialect on the interpreter request.","Church networks are often the real information channel; a mailed notice may not be.","Transportation and distance in Greater Minnesota counties."],"whoToInvolve":["Language access lead or interpreter services, with the dialect written on the request.","Equity Director for the administration or the person responsible for the program.","Community partner organizations identified in this brief, with a clear purpose, role, compensation, and plan to report back.","Karen-led organizations in Minnesota, as partners."],"whatNotToAssume":["Do not assume a smile or quiet endurance is consent.","Do not rely on a single news story for cultural context about Burma or Myanmar.","Do not assume the family lives in the Twin Cities."],"source0Label":"Community self-description","source0Note":"Community-informed description is pending source and representation review.","source0Href":""}},{"surfaceId":"community-brief.oromo","routePattern":"/minnesota-communities/oromo","staffLabel":"Oromo","scopePolicy":"inheritable","fieldContract":[{"key":"title","label":"Brief title","kind":"short","required":true,"maxLength":300},{"key":"kicker","label":"Brief section label","kind":"short","required":true,"maxLength":300},{"key":"owner","label":"Maintainer","kind":"short","required":true,"maxLength":300},{"key":"languages","label":"Languages named in the brief","kind":"string-list","required":true,"maxLength":2000},{"key":"whoAndWhere","label":"Who and where","kind":"long","required":true,"maxLength":4000},{"key":"whyItMatters","label":"Why it matters for DHS work","kind":"long","required":true,"maxLength":4000},{"key":"withinGroupDiversity","label":"Differences within the community","kind":"long","required":true,"maxLength":4000},{"key":"preferredNames","label":"Preferred names and terms","kind":"string-list","required":true,"maxLength":2000},{"key":"alsoUsedNames","label":"Other names and terms","kind":"string-list","required":false,"maxLength":2000},{"key":"nameNote","label":"Naming guidance","kind":"long","required":true,"maxLength":4000},{"key":"nameUncertainty","label":"What is still unclear","kind":"long","required":false,"maxLength":4000},{"key":"whatToAsk","label":"What to ask","kind":"string-list","required":true,"maxLength":2000},{"key":"accessChecks","label":"Access checks","kind":"string-list","required":true,"maxLength":2000},{"key":"whoToInvolve","label":"Who to involve","kind":"string-list","required":true,"maxLength":2000},{"key":"whatNotToAssume","label":"What not to assume","kind":"string-list","required":true,"maxLength":2000},{"key":"source0Label","label":"Source 1: name","kind":"short","required":true,"maxLength":300},{"key":"source0Note","label":"Source 1: note","kind":"long","required":true,"maxLength":4000},{"key":"source0Href","label":"Source 1: destination","kind":"url","required":false,"maxLength":2000}],"protectedFields":["status","reviewDate","representationReview","tribalGate","provenance","relatedPathIds","tags"],"requiredReviewDimensions":["language_alignment","factual_currentness","accessibility","scope","placement","rights_and_consent","community_representation"],"approvedValues":{"title":"Oromo Minnesotans","kicker":"Community brief","owner":"Equity and Inclusion Operations Consultant","languages":["Afaan Oromoo","Amharic (some)","English"],"whoAndWhere":"Oromo people are the largest nation in the Horn of Africa by language; there is no Oromo nation-state. Minnesota holds one of the largest Oromo communities outside Africa, concentrated in the Twin Cities. Counts disagree widely by method; date the number you cite.","whyItMatters":"Oromo is distinct from Somali and Amharic, and 'Ethiopian' is not a substitute for Oromo identity. An interpreter requested only as 'Ethiopian' may not meet the person's language needs. Oromo naming practices are also distinct from Amharic and Somali naming practices.","withinGroupDiversity":"Islam, Christianity, and Waaqeffanna all live here; do not assume a Somali religious pattern. U.S.-born children may have never lived in Oromia.","preferredNames":["Oromo","Oromo Minnesotan"],"alsoUsedNames":["Ethiopian (umbrella; not a substitute)"],"nameNote":"Book Afaan Oromoo on the interpreter line. Ask how names appear on documents.","nameUncertainty":"Community counts range widely between community estimates and census-based figures; state the source and date.","whatToAsk":["Should we book Afaan Oromoo?","Who should be in the room?","How would you like to be addressed?"],"accessChecks":["Afaan Oromoo, not Amharic or Somali, on the request.","Translated notices reviewed by an Afaan Oromoo speaker.","Greater Minnesota households exist; do not assume the metro."],"whoToInvolve":["Language access lead or interpreter services, with the dialect written on the request.","Equity Director for the administration or the person responsible for the program.","Community partner organizations identified in this brief, with a clear purpose, role, compensation, and plan to report back.","Oromo community organizations and congregations the family names."],"whatNotToAssume":["Do not use a Somali or broad 'Ethiopian' brief in place of Oromo-specific context.","Keep the service meeting focused on the person's needs rather than asking them to explain or resolve Ethiopian politics.","Do not assume a religious pattern."],"source0Label":"Minnesota Compass (Ethiopian umbrella profile)","source0Note":"Umbrella count; not an Oromo census.","source0Href":"https://www.mncompass.org/"}},{"surfaceId":"community-brief.african-american","routePattern":"/minnesota-communities/african-american","staffLabel":"African American","scopePolicy":"inheritable","fieldContract":[{"key":"title","label":"Brief title","kind":"short","required":true,"maxLength":300},{"key":"kicker","label":"Brief section label","kind":"short","required":true,"maxLength":300},{"key":"owner","label":"Maintainer","kind":"short","required":true,"maxLength":300},{"key":"languages","label":"Languages named in the brief","kind":"string-list","required":true,"maxLength":2000},{"key":"whoAndWhere","label":"Who and where","kind":"long","required":true,"maxLength":4000},{"key":"whyItMatters","label":"Why it matters for DHS work","kind":"long","required":true,"maxLength":4000},{"key":"withinGroupDiversity","label":"Differences within the community","kind":"long","required":true,"maxLength":4000},{"key":"preferredNames","label":"Preferred names and terms","kind":"string-list","required":true,"maxLength":2000},{"key":"alsoUsedNames","label":"Other names and terms","kind":"string-list","required":false,"maxLength":2000},{"key":"nameNote","label":"Naming guidance","kind":"long","required":true,"maxLength":4000},{"key":"nameUncertainty","label":"What is still unclear","kind":"long","required":false,"maxLength":4000},{"key":"whatToAsk","label":"What to ask","kind":"string-list","required":true,"maxLength":2000},{"key":"accessChecks","label":"Access checks","kind":"string-list","required":true,"maxLength":2000},{"key":"whoToInvolve","label":"Who to involve","kind":"string-list","required":true,"maxLength":2000},{"key":"whatNotToAssume","label":"What not to assume","kind":"string-list","required":true,"maxLength":2000},{"key":"deeper0Heading","label":"Deeper context 1: heading","kind":"short","required":true,"maxLength":300},{"key":"deeper0Body","label":"Deeper context 1: explanation","kind":"long","required":true,"maxLength":4000},{"key":"deeper1Heading","label":"Deeper context 2: heading","kind":"short","required":true,"maxLength":300},{"key":"deeper1Body","label":"Deeper context 2: explanation","kind":"long","required":true,"maxLength":4000},{"key":"source0Label","label":"Source 1: name","kind":"short","required":true,"maxLength":300},{"key":"source0Note","label":"Source 1: note","kind":"long","required":true,"maxLength":4000},{"key":"source0Href","label":"Source 1: destination","kind":"url","required":false,"maxLength":2000},{"key":"source1Label","label":"Source 2: name","kind":"short","required":true,"maxLength":300},{"key":"source1Note","label":"Source 2: note","kind":"long","required":true,"maxLength":4000},{"key":"source1Href","label":"Source 2: destination","kind":"url","required":false,"maxLength":2000},{"key":"observance0Title","label":"Observance 1: name","kind":"short","required":true,"maxLength":300},{"key":"observance0When","label":"Observance 1: timing","kind":"short","required":true,"maxLength":300},{"key":"observance0AtWork","label":"Observance 1: workplace guidance","kind":"long","required":true,"maxLength":4000}],"protectedFields":["status","reviewDate","representationReview","tribalGate","provenance","relatedPathIds","tags"],"requiredReviewDimensions":["language_alignment","factual_currentness","accessibility","scope","placement","rights_and_consent","community_representation"],"approvedValues":{"title":"African American and Black Minnesotans","kicker":"Community brief","owner":"Equity and Inclusion Operations Consultant","languages":["English"],"whoAndWhere":"U.S.-born African Americans in Minnesota carry the history of enslavement, the Great Migration, the destruction of Rondo, Northside Minneapolis, policing, and the murder of George Floyd. Minnesota ranks high on quality of life and produces some of the worst racial gaps in the country in education, wealth, homeownership, and criminal legal contact; this has been called the Minnesota Paradox.","whyItMatters":"Color-blind approaches can hide the unequal results a process continues to produce, including disproportionate out-of-home placement. Minnesota law on African American family preservation requires active efforts and family cultural values in case planning; a training is not a substitute.","withinGroupDiversity":"African immigrants and refugees—including Liberian, Nigerian, Ethiopian, Ghanaian, Somali, Oromo, and other communities—come from different nations, languages, and class backgrounds, and may have different relationships to 'Black' identity in the United States. These communities are not interchangeable.","preferredNames":["Black","African American"],"alsoUsedNames":["Black Minnesotan","African immigrant communities by their own names"],"nameNote":"Ask which term the person uses. Do not assume that guidance written for Somali Minnesotans applies to an African American family from Chicago.","nameUncertainty":"","whatToAsk":["Who is family here: extended kin, fictive kin, church, community? Who should be in the room?","What has happened before with this agency or with police-involved referrals that we should know?","What would make this process feel fair to you?"],"accessChecks":["Case plans that do not recognize a grandmother, aunt, or other important kin may exclude meaningful family support. Check how the form defines family.","Plain language in notices; appeal rights explained in person.","Review who is denied, delayed, or placed by race in your program's own data before you design."],"whoToInvolve":["Equity Director or administration steward.","Black-led community organizations named by the family or listed in the relevant program resources, with compensation and report-back.","The policy or legal owner for any question about the family-preservation statute; this program does not interpret it."],"whatNotToAssume":["Do not assume 'Minnesota Nice' neutrality is neutral for this family.","Do not fold African immigrant households into this brief, or this family into an immigrant brief.","Do not read directness as hostility or quiet as agreement.","Understand the state's documented racial disparities before making decisions that affect families."],"deeper0Heading":"Child welfare and family preservation","deeper0Body":"African American children in Minnesota have been about twice as likely as white peers to be placed in out-of-home care. The Minnesota African American Family Preservation and Child Welfare Disproportionality Act requires active efforts and incorporation of the family's social and cultural values in case planning and reunification. That is statute; verify the current text with the policy owner.","deeper1Heading":"Kinship and family preservation","deeper1Body":"Extended kin, fictive kin, churches, and community care can be central sources of family support. Ancestral and spiritual practices vary and may include Baptist, COGIC, Muslim, African traditional, or no religious practice. Ask the family what matters to them.","source0Label":"Minnesota African American Family Preservation and Child Welfare Disproportionality Act","source0Note":"Verify current statute text with the policy owner; this program does not interpret it.","source0Href":"","source1Label":"Minnesota Compass, Black or African American profile","source1Note":"Include the source date when citing this information.","source1Href":"https://www.mncompass.org/","observance0Title":"Juneteenth","observance0When":"June 19","observance0AtWork":"Observed as a holiday; do not schedule required sessions."}},{"surfaceId":"community-brief.latino","routePattern":"/minnesota-communities/latino","staffLabel":"Latino","scopePolicy":"inheritable","fieldContract":[{"key":"title","label":"Brief title","kind":"short","required":true,"maxLength":300},{"key":"kicker","label":"Brief section label","kind":"short","required":true,"maxLength":300},{"key":"owner","label":"Maintainer","kind":"short","required":true,"maxLength":300},{"key":"languages","label":"Languages named in the brief","kind":"string-list","required":true,"maxLength":2000},{"key":"whoAndWhere","label":"Who and where","kind":"long","required":true,"maxLength":4000},{"key":"whyItMatters","label":"Why it matters for DHS work","kind":"long","required":true,"maxLength":4000},{"key":"withinGroupDiversity","label":"Differences within the community","kind":"long","required":true,"maxLength":4000},{"key":"preferredNames","label":"Preferred names and terms","kind":"string-list","required":true,"maxLength":2000},{"key":"alsoUsedNames","label":"Other names and terms","kind":"string-list","required":false,"maxLength":2000},{"key":"nameNote","label":"Naming guidance","kind":"long","required":true,"maxLength":4000},{"key":"nameUncertainty","label":"What is still unclear","kind":"long","required":false,"maxLength":4000},{"key":"whatToAsk","label":"What to ask","kind":"string-list","required":true,"maxLength":2000},{"key":"accessChecks","label":"Access checks","kind":"string-list","required":true,"maxLength":2000},{"key":"whoToInvolve","label":"Who to involve","kind":"string-list","required":true,"maxLength":2000},{"key":"whatNotToAssume","label":"What not to assume","kind":"string-list","required":true,"maxLength":2000},{"key":"source0Label","label":"Source 1: name","kind":"short","required":true,"maxLength":300},{"key":"source0Note","label":"Source 1: note","kind":"long","required":true,"maxLength":4000},{"key":"source0Href","label":"Source 1: destination","kind":"url","required":false,"maxLength":2000}],"protectedFields":["status","reviewDate","representationReview","tribalGate","provenance","relatedPathIds","tags"],"requiredReviewDimensions":["language_alignment","factual_currentness","accessibility","scope","placement","rights_and_consent","community_representation"],"approvedValues":{"title":"Latino and Spanish-speaking Minnesotans","kicker":"Community brief","owner":"Equity and Inclusion Operations Consultant","languages":["Spanish (many national varieties)","Indigenous languages of Mexico and Central America (some households)","English"],"whoAndWhere":"Latino Minnesotans include long-settled families, recent arrivals, and U.S.-born generations with roots in Mexico, Central and South America, Puerto Rico, and the Caribbean. A large share lives outside the Twin Cities, in dairy, meatpacking, and farm counties.","whyItMatters":"'Spanish' on a form is one language among many, and some households speak an Indigenous language first. Immigration status fear shapes help-seeking even for citizens in mixed-status families. Greater Minnesota distance and shift work are access facts.","withinGroupDiversity":"National origin, Indigenous identity, generation, faith, class, and legal status differ widely. Puerto Ricans are U.S. citizens. Do not assume one 'Hispanic' culture.","preferredNames":["Latino","Latina","Hispanic (used by many)","national-origin terms (Mexican, Salvadoran, Puerto Rican)"],"alsoUsedNames":["Latinx","Latine (used by some, contested)"],"nameNote":"Two surnames are common, and forms that keep only one can create errors in a person's record. Ask which term the person uses for themselves.","nameUncertainty":"Term preference is contested and generational; ask.","whatToAsk":["Which language, and is Spanish the first language?","How are your surnames written on your documents?","Who should be in the room?","What times work with your shift?"],"accessChecks":["Spanish interpreter with the right variety; ask about Indigenous languages.","Forms accept two surnames.","No requirement to disclose immigration status for a listening session.","Evening or weekend options; phone paths that do not require broadband."],"whoToInvolve":["Language access lead or interpreter services, with the dialect written on the request.","Equity Director for the administration or the person responsible for the program.","Community partner organizations identified in this brief, with a clear purpose, role, compensation, and plan to report back.","Latino-led organizations and parish networks the family names."],"whatNotToAssume":["Do not assume immigration status, or that citizens are unaffected by status fear.","Do not assume the metro.","Do not assume Spanish is the first language."],"source0Label":"Minnesota Compass, Hispanic or Latino profile","source0Note":"Include the source date when citing this information; the Greater Minnesota share is notable.","source0Href":"https://www.mncompass.org/"}},{"surfaceId":"community-brief.vietnamese","routePattern":"/minnesota-communities/vietnamese","staffLabel":"Vietnamese","scopePolicy":"inheritable","fieldContract":[{"key":"title","label":"Brief title","kind":"short","required":true,"maxLength":300},{"key":"kicker","label":"Brief section label","kind":"short","required":true,"maxLength":300},{"key":"owner","label":"Maintainer","kind":"short","required":true,"maxLength":300},{"key":"languages","label":"Languages named in the brief","kind":"string-list","required":true,"maxLength":2000},{"key":"whoAndWhere","label":"Who and where","kind":"long","required":true,"maxLength":4000},{"key":"whyItMatters","label":"Why it matters for DHS work","kind":"long","required":true,"maxLength":4000},{"key":"withinGroupDiversity","label":"Differences within the community","kind":"long","required":true,"maxLength":4000},{"key":"preferredNames","label":"Preferred names and terms","kind":"string-list","required":true,"maxLength":2000},{"key":"alsoUsedNames","label":"Other names and terms","kind":"string-list","required":false,"maxLength":2000},{"key":"nameNote","label":"Naming guidance","kind":"long","required":true,"maxLength":4000},{"key":"nameUncertainty","label":"What is still unclear","kind":"long","required":f