},{"key":"whoToInvolve","label":"Who to involve","kind":"string-list","required":true,"maxLength":2000},{"key":"whatNotToAssume","label":"What not to assume","kind":"string-list","required":true,"maxLength":2000},{"key":"source0Label","label":"Source 1: name","kind":"short","required":true,"maxLength":300},{"key":"source0Note","label":"Source 1: note","kind":"long","required":true,"maxLength":4000},{"key":"source0Href","label":"Source 1: destination","kind":"url","required":false,"maxLength":2000}],"protectedFields":["status","reviewDate","representationReview","tribalGate","provenance","relatedPathIds","tags"],"requiredReviewDimensions":["language_alignment","factual_currentness","accessibility","scope","placement","rights_and_consent","community_representation"],"approvedValues":{"title":"Lao Minnesotans","kicker":"Community brief","owner":"Equity and Inclusion Operations Consultant","languages":["Lao","English"],"whoAndWhere":"Lao Minnesotans arrived as refugees after 1975 and through later family reunification; Lao and Hmong are distinct peoples from the same country.","whyItMatters":"'Laotian' on a form can mean Lao, Hmong, or other groups; book the actual language.","withinGroupDiversity":"Buddhist and Christian households; generations differ on language.","preferredNames":["Lao"],"alsoUsedNames":["Laotian (national label)"],"nameNote":"Ask which language and how names appear on documents.","nameUncertainty":"","whatToAsk":["Lao interpreter, or a different language?","Who should be in the room?"],"accessChecks":["Language, not nationality, on the request.","Translated vital notices reviewed by a Lao speaker."],"whoToInvolve":["Language access lead or interpreter services, with the dialect written on the request.","Equity Director for the administration or the person responsible for the program.","Community partner organizations identified in this brief, with a clear purpose, role, compensation, and plan to report back."],"whatNotToAssume":["Do not assume Hmong and Lao are the same brief."],"source0Label":"Community self-description","source0Note":"A community-informed source and representation review are still needed.","source0Href":""}},{"surfaceId":"community-brief.russian-speaking","routePattern":"/minnesota-communities/russian-speaking","staffLabel":"Russian Speaking","scopePolicy":"inheritable","fieldContract":[{"key":"title","label":"Brief title","kind":"short","required":true,"maxLength":300},{"key":"kicker","label":"Brief section label","kind":"short","required":true,"maxLength":300},{"key":"owner","label":"Maintainer","kind":"short","required":true,"maxLength":300},{"key":"languages","label":"Languages named in the brief","kind":"string-list","required":true,"maxLength":2000},{"key":"whoAndWhere","label":"Who and where","kind":"long","required":true,"maxLength":4000},{"key":"whyItMatters","label":"Why it matters for DHS work","kind":"long","required":true,"maxLength":4000},{"key":"withinGroupDiversity","label":"Differences within the community","kind":"long","required":true,"maxLength":4000},{"key":"preferredNames","label":"Preferred names and terms","kind":"string-list","required":true,"maxLength":2000},{"key":"alsoUsedNames","label":"Other names and terms","kind":"string-list","required":false,"maxLength":2000},{"key":"nameNote","label":"Naming guidance","kind":"long","required":true,"maxLength":4000},{"key":"nameUncertainty","label":"What is still unclear","kind":"long","required":false,"maxLength":4000},{"key":"whatToAsk","label":"What to ask","kind":"string-list","required":true,"maxLength":2000},{"key":"accessChecks","label":"Access checks","kind":"string-list","required":true,"maxLength":2000},{"key":"whoToInvolve","label":"Who to involve","kind":"string-list","required":true,"maxLength":2000},{"key":"whatNotToAssume","label":"What not to assume","kind":"string-list","required":true,"maxLength":2000},{"key":"source0Label","label":"Source 1: name","kind":"short","required":true,"maxLength":300},{"key":"source0Note","label":"Source 1: note","kind":"long","required":true,"maxLength":4000},{"key":"source0Href","label":"Source 1: destination","kind":"url","required":false,"maxLength":2000}],"protectedFields":["status","reviewDate","representationReview","tribalGate","provenance","relatedPathIds","tags"],"requiredReviewDimensions":["language_alignment","factual_currentness","accessibility","scope","placement","rights_and_consent","community_representation"],"approvedValues":{"title":"Russian-speaking Minnesotans","kicker":"Community brief","owner":"Equity and Inclusion Operations Consultant","languages":["Russian","Ukrainian","English"],"whoAndWhere":"Russian-speaking Minnesotans come from many countries of the former Soviet Union, including refugees of earlier decades and recent Ukrainian arrivals.","whyItMatters":"Russian is a shared language across people with very different national identities; for Ukrainian households, assuming Russian identity can be a harm. Book the language the person asks for.","withinGroupDiversity":"Jewish, Orthodox Christian, evangelical, and secular households; national identities that may be in conflict.","preferredNames":["Russian-speaking (as a language group)","national-origin terms (Ukrainian, Belarusian, and others)"],"alsoUsedNames":[],"nameNote":"Patronymics are common; ask how the person wants to be addressed.","nameUncertainty":"National identity is sensitive; ask rather than infer from language.","whatToAsk":["Which language should we book: Russian or Ukrainian?","How would you like to be addressed?","Who should be in the room?"],"accessChecks":["Interpreter language matches the request.","Notices in the requested language, reviewed."],"whoToInvolve":["Language access lead or interpreter services, with the dialect written on the request.","Equity Director for the administration or the person responsible for the program.","Community partner organizations identified in this brief, with a clear purpose, role, compensation, and plan to report back."],"whatNotToAssume":["Do not infer nationality or politics from language.","Do not assume religion."],"source0Label":"Community self-description","source0Note":"A community-informed source and representation review are still needed.","source0Href":""}},{"surfaceId":"community-brief.arabic-speaking","routePattern":"/minnesota-communities/arabic-speaking","staffLabel":"Arabic Speaking","scopePolicy":"inheritable","fieldContract":[{"key":"title","label":"Brief title","kind":"short","required":true,"maxLength":300},{"key":"kicker","label":"Brief section label","kind":"short","required":true,"maxLength":300},{"key":"owner","label":"Maintainer","kind":"short","required":true,"maxLength":300},{"key":"languages","label":"Languages named in the brief","kind":"string-list","required":true,"maxLength":2000},{"key":"whoAndWhere","label":"Who and where","kind":"long","required":true,"maxLength":4000},{"key":"whyItMatters","label":"Why it matters for DHS work","kind":"long","required":true,"maxLength":4000},{"key":"withinGroupDiversity","label":"Differences within the community","kind":"long","required":true,"maxLength":4000},{"key":"preferredNames","label":"Preferred names and terms","kind":"string-list","required":true,"maxLength":2000},{"key":"alsoUsedNames","label":"Other names and terms","kind":"string-list","required":false,"maxLength":2000},{"key":"nameNote","label":"Naming guidance","kind":"long","required":true,"maxLength":4000},{"key":"nameUncertainty","label":"What is still unclear","kind":"long","required":false,"maxLength":4000},{"key":"whatToAsk","label":"What to ask","kind":"string-list","required":true,"maxLength":2000},{"key":"accessChecks","label":"Access checks","kind":"string-list","required":true,"maxLength":2000},{"key":"whoToInvolve","label":"Who to involve","kind":"string-list","required":true,"maxLength":2000},{"key":"whatNotToAssume","label":"What not to assume","kind":"string-list","required":true,"maxLength":2000},{"key":"source0Label","label":"Source 1: name","kind":"short","required":true,"maxLength":300},{"key":"source0Note","label":"Source 1: note","kind":"long","required":true,"maxLength":4000},{"key":"source0Href","label":"Source 1: destination","kind":"url","required":false,"maxLength":2000}],"protectedFields":["status","reviewDate","representationReview","tribalGate","provenance","relatedPathIds","tags"],"requiredReviewDimensions":["language_alignment","factual_currentness","accessibility","scope","placement","rights_and_consent","community_representation"],"approvedValues":{"title":"Arabic-speaking Minnesotans","kicker":"Community brief","owner":"Equity and Inclusion Operations Consultant","languages":["Arabic (many regional varieties)","English"],"whoAndWhere":"Arabic-speaking Minnesotans come from many countries, including Iraq, Syria, Lebanon, Egypt, Sudan, Yemen, and Palestine, with refugee, immigrant, and U.S.-born generations.","whyItMatters":"Arabic varieties differ enough that an interpreter from one region may not serve another well; Arabic is also a religious language for many non-Arab Muslims, which is not the same as a household language.","withinGroupDiversity":"Muslim, Christian, and secular households; national identities and dialects vary widely.","preferredNames":["Arabic-speaking (as a language group)","national-origin terms"],"alsoUsedNames":["Arab American"],"nameNote":"Ask which variety of Arabic and how names appear on documents.","nameUncertainty":"","whatToAsk":["Which variety of Arabic, and from which country?","Would you like a gender-matched interpreter?","Who should be in the room?"],"accessChecks":["Regional variety on the request when possible.","Vital notices translated with human review."],"whoToInvolve":["Language access lead or interpreter services, with the dialect written on the request.","Equity Director for the administration or the person responsible for the program.","Community partner organizations identified in this brief, with a clear purpose, role, compensation, and plan to report back."],"whatNotToAssume":["Do not assume religion from language.","Do not assume Somali or Oromo households want Arabic; ask."],"source0Label":"Community self-description","source0Note":"A community-informed source and representation review are still needed.","source0Href":""}},{"surfaceId":"community-brief.deaf-deafblind-hard-of-hearing","routePattern":"/minnesota-communities/deaf-deafblind-hard-of-hearing","staffLabel":"Deaf Deafblind Hard Of Hearing","scopePolicy":"inheritable","fieldContract":[{"key":"title","label":"Brief title","kind":"short","required":true,"maxLength":300},{"key":"kicker","label":"Brief section label","kind":"short","required":true,"maxLength":300},{"key":"owner","label":"Maintainer","kind":"short","required":true,"maxLength":300},{"key":"languages","label":"Languages named in the brief","kind":"string-list","required":true,"maxLength":2000},{"key":"whoAndWhere","label":"Who and where","kind":"long","required":true,"maxLength":4000},{"key":"whyItMatters","label":"Why it matters for DHS work","kind":"long","required":true,"maxLength":4000},{"key":"withinGroupDiversity","label":"Differences within the community","kind":"long","required":true,"maxLength":4000},{"key":"preferredNames","label":"Preferred names and terms","kind":"string-list","required":true,"maxLength":2000},{"key":"alsoUsedNames","label":"Other names and terms","kind":"string-list","required":false,"maxLength":2000},{"key":"nameNote","label":"Naming guidance","kind":"long","required":true,"maxLength":4000},{"key":"nameUncertainty","label":"What is still unclear","kind":"long","required":false,"maxLength":4000},{"key":"whatToAsk","label":"What to ask","kind":"string-list","required":true,"maxLength":2000},{"key":"accessChecks","label":"Access checks","kind":"string-list","required":true,"maxLength":2000},{"key":"whoToInvolve","label":"Who to involve","kind":"string-list","required":true,"maxLength":2000},{"key":"whatNotToAssume","label":"What not to assume","kind":"string-list","required":true,"maxLength":2000},{"key":"source0Label","label":"Source 1: name","kind":"short","required":true,"maxLength":300},{"key":"source0Note","label":"Source 1: note","kind":"long","required":true,"maxLength":4000},{"key":"source0Href","label":"Source 1: destination","kind":"url","required":false,"maxLength":2000}],"protectedFields":["status","reviewDate","representationReview","tribalGate","provenance","relatedPathIds","tags"],"requiredReviewDimensions":["language_alignment","factual_currentness","accessibility","scope","placement","rights_and_consent","community_representation"],"approvedValues":{"title":"Deaf, DeafBlind, and hard of hearing Minnesotans","kicker":"Community brief","owner":"Equity and Inclusion Operations Consultant","languages":["American Sign Language","Protactile and tactile ASL (DeafBlind)","English (written, captioned)"],"whoAndWhere":"Deaf people who use American Sign Language are a cultural and linguistic community, not only a disability category. Hard of hearing and late-deafened people may prefer captioning and assistive listening. DeafBlind people may use tactile or Protactile communication.","whyItMatters":"Effective communication is a legal obligation. Exchanging written notes is not equally effective for a Deaf person who uses sign language, and a family member is not an interpreter. Your process must work with video relay and captioned phone calls.","withinGroupDiversity":"ASL users, oral communicators, cochlear implant users, late-deafened elders, DeafBlind people, and Deaf people from immigrant communities who use other sign languages.","preferredNames":["Deaf (cultural, capital D)","deaf","hard of hearing","DeafBlind"],"alsoUsedNames":[],"nameNote":"Do not use 'hearing impaired'. Ask the person's preference.","nameUncertainty":"","whatToAsk":["How would you like to communicate today: ASL interpreter, captioning, written English, or something else?","Do you use video relay or a captioned phone?","Who should be in the room?"],"accessChecks":["Qualified ASL interpreter or CART booked in advance; not a family member.","Videos captioned; phone processes have a relay-compatible path.","Visual alerts in waiting areas; written materials in plain language."],"whoToInvolve":["Accessibility or ADA coordinator.","Minnesota's Deaf and Hard of Hearing Services Division as a resource (verify current contact).","Equity Director or administration steward."],"whatNotToAssume":["Do not assume lip reading is enough.","Do not assume written English is a first language for a Deaf ASL user.","Do not assume a hearing aid means full access."],"source0Label":"ADA Title II effective communication","source0Note":"External; verify at ada.gov.","source0Href":"https://www.ada.gov/"}},{"surfaceId":"community-brief.rural","routePattern":"/minnesota-communities/rural","staffLabel":"Rural","scopePolicy":"inheritable","fieldContract":[{"key":"title","label":"Brief title","kind":"short","required":true,"maxLength":300},{"key":"kicker","label":"Brief section label","kind":"short","required":true,"maxLength":300},{"key":"owner","label":"Maintainer","kind":"short","required":true,"maxLength":300},{"key":"languages","label":"Languages named in the brief","kind":"string-list","required":true,"maxLength":2000},{"key":"whoAndWhere","label":"Who and where","kind":"long","required":true,"maxLength":4000},{"key":"whyItMatters","label":"Why it matters for DHS work","kind":"long","required":true,"maxLength":4000},{"key":"withinGroupDiversity","label":"Differences within the community","kind":"long","required":true,"maxLength":4000},{"key":"preferredNames","label":"Preferred names and terms","kind":"string-list","required":true,"maxLength":2000},{"key":"alsoUsedNames","label":"Other names and terms","kind":"string-list","required":false,"maxLength":2000},{"key":"nameNote","label":"Naming guidance","kind":"long","required":true,"maxLength":4000},{"key":"nameUncertainty","label":"What is still unclear","kind":"long","required":false,"maxLength":4000},{"key":"whatToAsk","label":"What to ask","kind":"string-list","required":true,"maxLength":2000},{"key":"accessChecks","label":"Access checks","kind":"string-list","required":true,"maxLength":2000},{"key":"whoToInvolve","label":"Who to involve","kind":"string-list","required":true,"maxLength":2000},{"key":"whatNotToAssume","label":"What not to assume","kind":"string-list","required":true,"maxLength":2000},{"key":"source0Label","label":"Source 1: name","kind":"short","required":true,"maxLength":300},{"key":"source0Note","label":"Source 1: note","kind":"long","required":true,"maxLength":4000},{"key":"source0Href","label":"Source 1: destination","kind":"url","required":false,"maxLength":2000}],"protectedFields":["status","reviewDate","representationReview","tribalGate","provenance","relatedPathIds","tags"],"requiredReviewDimensions":["language_alignment","factual_currentness","accessibility","scope","placement","rights_and_consent","community_representation"],"approvedValues":{"title":"Rural and Greater Minnesota (place, not a race)","kicker":"Place brief","owner":"Equity and Inclusion Operations Consultant","languages":["English","Spanish, Somali, Karen, and others by county"],"whoAndWhere":"Rural experience is shaped by geography and infrastructure, including broadband, distance, hospital closures, and county capacity. Farming and mining communities are not the same. Somali families in Worthington, Mexican families in dairy counties, and the eleven Tribal Nations must be considered from the beginning.","whyItMatters":"A service that depends on reliable broadband can exclude people. County human services is often where people actually receive help. A missed visit may reflect fuel costs or winter roads rather than refusal.","withinGroupDiversity":"Iron Range, prairie, forest, and border towns are not one region. Name the town.","preferredNames":["Greater Minnesota","rural Minnesota"],"alsoUsedNames":["outstate (avoid; read as dismissive by some)"],"nameNote":"Do not use rural as code for white.","nameUncertainty":"","whatToAsk":["What is the nearest office or partner, and how far is it?","Does a phone process work for you? Does mail?","Who in your town helps with paperwork?"],"accessChecks":["Phone and paper paths that do not require broadband.","Office hours and distance as burden.","Open the people brief for the household together with this place brief."],"whoToInvolve":["County human services partners.","Equity Director or administration steward.","Local organizations named by the household."],"whatNotToAssume":["Do not romanticize or pathologize.","Do not assume voicemail or email works.","Do not treat a no-show as character."],"source0Label":"Minnesota Compass, geography profiles","source0Note":"People-page shares outside the Twin Cities vary by community; date them.","source0Href":"https://www.mncompass.org/"}},{"surfaceId":"community-brief.tribal-nations","routePattern":"/minnesota-communities/tribal-nations","staffLabel":"Tribal Nations","scopePolicy":"inheritable","fieldContract":[{"key":"title","label":"Brief title","kind":"short","required":true,"maxLength":300},{"key":"kicker","label":"Brief section label","kind":"short","required":true,"maxLength":300},{"key":"owner","label":"Maintainer","kind":"short","required":true,"maxLength":300},{"key":"languages","label":"Languages named in the brief","kind":"string-list","required":true,"maxLength":2000},{"key":"whoAndWhere","label":"Who and where","kind":"long","required":true,"maxLength":4000},{"key":"whyItMatters","label":"Why it matters for DHS work","kind":"long","required":true,"maxLength":4000},{"key":"withinGroupDiversity","label":"Differences within the community","kind":"long","required":true,"maxLength":4000},{"key":"preferredNames","label":"Preferred names and terms","kind":"string-list","required":true,"maxLength":2000},{"key":"alsoUsedNames","label":"Other names and terms","kind":"string-list","required":false,"maxLength":2000},{"key":"nameNote","label":"Naming guidance","kind":"long","required":true,"maxLength":4000},{"key":"nameUncertainty","label":"What is still unclear","kind":"long","required":false,"maxLength":4000},{"key":"whatToAsk","label":"What to ask","kind":"string-list","required":true,"maxLength":2000},{"key":"accessChecks","label":"Access checks","kind":"string-list","required":true,"maxLength":2000},{"key":"whoToInvolve","label":"Who to involve","kind":"string-list","required":true,"maxLength":2000},{"key":"whatNotToAssume","label":"What not to assume","kind":"string-list","required":true,"maxLength":2000},{"key":"source0Label","label":"Source 1: name","kind":"short","required":true,"maxLength":300},{"key":"source0Note","label":"Source 1: note","kind":"long","required":true,"maxLength":4000},{"key":"source0Href","label":"Source 1: destination","kind":"url","required":false,"maxLength":2000}],"protectedFields":["status","reviewDate","representationReview","tribalGate","provenance","relatedPathIds","tags"],"requiredReviewDimensions":["language_alignment","factual_currentness","accessibility","scope","placement","rights_and_consent","community_representation"],"approvedValues":{"title":"Tribal Nations of Minnesota","kicker":"Sovereignty and consultation","owner":"Equity and Inclusion Operations Consultant","languages":["Ojibwe","Dakota","English"],"whoAndWhere":"Eleven federally recognized Tribal Nations share geography with Minnesota. Each is a sovereign government with its own name, laws, leadership, and consultation process. Urban Native people also live throughout the state. This page explains when staff should seek government-to-government guidance; it does not provide Nation-specific guidance.","whyItMatters":"When work may affect a Tribal Nation, Native children, Tribal data, services, or land, contact the designated Tribal relations office or liaison before planning consultation or engagement. A general community meeting is not government-to-government consultation.","withinGroupDiversity":"Each Nation is distinct. Do not infer a person's Tribal citizenship, community ties, language, or residence.","preferredNames":["The Nation's own name (for example Red Lake Nation, Lower Sioux Indian Community)"],"alsoUsedNames":["American Indian","Native American","Indigenous"],"nameNote":"Name the Nation. Do not use a demographic count as a substitute for a government.","nameUncertainty":"","whatToAsk":["Could this work affect a Tribal Nation, Native children, Tribal data, services, or land? If so, contact the designated Tribal relations office or liaison before planning consultation or engagement."],"accessChecks":["This referral page does not provide Nation-specific access guidance. Ask the designated Tribal relations office or liaison which process and contacts apply."],"whoToInvolve":["Before planning consultation or engagement, contact the Office of Indian Policy or current designated Tribal relations office or liaison and follow the required process.","Work with the Nation's government through the process it designates."],"whatNotToAssume":["Do not infer Tribal citizenship or community ties.","Do not place a sovereign Nation in a general community partner list.","Do not use general cultural information as a substitute for consultation with the Nation."],"source0Label":"DHS Tribal and Urban Indian Relations","source0Note":"Use the current DHS contact and guidance before planning consultation or engagement.","source0Href":"https://mn.gov/dhs/partners-and-providers/program-overviews/tribal-and-urban-indian-relations/"}}]$pac_registry$::jsonb;
  seed jsonb;
  seed_surface_id text;
  seed_scope_id text;
  seed_fields jsonb;
  seed_protected text[];
  seed_reviews text[];
  seed_document jsonb;
  seed_revision_id uuid;
  seed_publish boolean;
  review_dimension text;
  existing_definition pac.surface_definitions%rowtype;
begin
  for seed in select value from jsonb_array_elements(registry_seed)
  loop
    seed_surface_id := seed ->> 'surfaceId';
    seed_publish := seed_surface_id not like 'community-brief.%';
    seed_fields := seed -> 'fieldContract';
    seed_protected := array(
      select value from jsonb_array_elements_text(coalesce(seed -> 'protectedFields', '[]'::jsonb))
    );
    seed_reviews := array(
      select value from jsonb_array_elements_text(seed -> 'requiredReviewDimensions')
    );
    seed_scope_id := case when seed ->> 'scopePolicy' = 'dsd' then 'dsd' else 'one-dhs' end;

    insert into pac.surface_definitions (
      surface_id, route_pattern, staff_label, scope_policy, schema_version,
      field_contract, protected_fields, required_review_dimensions,
      linked_content_item_id, active, registered_by
    ) values (
      seed_surface_id,
      seed ->> 'routePattern',
      seed ->> 'staffLabel',
      seed ->> 'scopePolicy',
      1,
      seed_fields,
      seed_protected,
      seed_reviews,
      null,
      true,
      'pac-forward-migration-0018'
    )
    on conflict (surface_id) do nothing;

    select * into strict existing_definition
    from pac.surface_definitions where surface_id = seed_surface_id;
    if existing_definition.route_pattern is distinct from seed ->> 'routePattern'
      or existing_definition.staff_label is distinct from seed ->> 'staffLabel'
      or existing_definition.scope_policy is distinct from seed ->> 'scopePolicy'
      or existing_definition.schema_version <> 1
      or existing_definition.field_contract is distinct from seed_fields
      or existing_definition.protected_fields is distinct from seed_protected
      or existing_definition.required_review_dimensions is distinct from seed_reviews
      or existing_definition.active is distinct from true then
      raise exception 'Existing editable surface % does not match the registered application contract', seed_surface_id
        using errcode = '55000';
    end if;

    seed_document := jsonb_build_object(
      'schemaVersion', 1,
      'surfaceId', seed_surface_id,
      'scope', seed_scope_id,
      'values', seed -> 'approvedValues'
    );
    perform pac.assert_valid_surface_document(seed_surface_id, seed_scope_id, seed_document);

    select revision.revision_id into seed_revision_id
    from pac.surface_revisions revision
    where revision.surface_id = seed_surface_id
      and revision.scope_id = seed_scope_id
      and revision.document = seed_document
      and revision.change_note = 'Initial owner-approved wording for governed review.'
    order by revision.revision_number
    limit 1;

    if seed_revision_id is null then
      if exists (
        select 1 from pac.surface_revisions revision
        where revision.surface_id = seed_surface_id and revision.scope_id = seed_scope_id
      ) then
        raise exception 'Existing editable surface % is missing its approved baseline', seed_surface_id
          using errcode = '55000';
      end if;

      insert into pac.surface_revisions (
        surface_id, scope_id, revision_number, document, change_note,
        required_review_dimensions, created_by, based_on_revision_id
      ) values (
        seed_surface_id, seed_scope_id, 1, seed_document,
        'Initial owner-approved wording for governed review.', seed_reviews,
        'pac-forward-migration-0018', null
      ) returning revision_id into seed_revision_id;

      foreach review_dimension in array seed_reviews
      loop
        insert into pac.surface_reviews (
          revision_id, dimension, status, note, reviewer_role, reviewer_id
        ) values (
          seed_revision_id, review_dimension,
          case when seed_publish then 'pass' else 'pending' end,
          case
            when seed_publish then 'Approved baseline wording registered with the application.'
            else 'Review is required before this community wording can be published.'
          end,
          'publishing_approver', 'pac-consultant-workspace-owner'
        );
      end loop;

      if seed_publish then
        insert into pac.surface_publication_decisions (
          surface_id, scope_id, revision_id, decision, gate_snapshot, reason, decided_by
        ) values (
          seed_surface_id, seed_scope_id, seed_revision_id, 'publish',
          jsonb_build_object(
            'requiredReviewsComplete', true,
            'registeredFieldsChecked', true,
            'staffLanguageChecked', true,
            'plainTextChecked', true,
            'iconsChecked', true,
            'exactApprovedCopyCaptured', true,
            'explicitOwnerApproval', true,
            'seedMigration', '0018_pac_editable_surfaces.sql'
          ),
          'Initial owner-approved staff wording.',
          'pac-forward-migration-0018'
        );

        insert into pac.surface_change_events (
          surface_id, scope_id, revision_id, publication_decision_id,
          action, detail, actor_id, actor_role
        )
        select seed_surface_id, seed_scope_id, seed_revision_id,
          decision_record.publication_decision_id, 'published',
          jsonb_build_object('initialApprovedCopy', true, 'staffCopyChanged', true),
          'pac-forward-migration-0018', 'migration'
        from pac.surface_publication_decisions decision_record
        where decision_record.surface_id = seed_surface_id
          and decision_record.scope_id = seed_scope_id
          and decision_record.revision_id = seed_revision_id
          and decision_record.decision = 'publish'
        order by decision_record.publication_decision_id desc
        limit 1;
      else
        insert into pac.surface_change_events (
          surface_id, scope_id, revision_id, action, detail, actor_id, actor_role
        ) values (
          seed_surface_id, seed_scope_id, seed_revision_id, 'draft_created',
          jsonb_build_object(
            'initialOwnerApprovedIngestion', true,
            'publicationPending', true,
            'representationReviewPending', true,
            'staffPublicationUnchanged', true
          ),
          'pac-forward-migration-0018', 'migration'
        );
      end if;
    elsif seed_publish and not exists (
      select 1 from pac.surface_publication_decisions decision_record
      where decision_record.surface_id = seed_surface_id
        and decision_record.scope_id = seed_scope_id
        and decision_record.revision_id = seed_revision_id
        and decision_record.decision = 'publish'
    ) then
      raise exception 'Approved editable surface % has no preserved publication decision', seed_surface_id
        using errcode = '55000';
    end if;
  end loop;
end;
$pac_seed$;

revoke all privileges on pac.surface_definitions from public, pac_app_runtime;
revoke all privileges on pac.surface_revisions from public, pac_app_runtime;
revoke all privileges on pac.surface_reviews from public, pac_app_runtime;
revoke all privileges on pac.surface_publication_decisions from public, pac_app_runtime;
revoke all privileges on pac.surface_change_events from public, pac_app_runtime;
revoke all privileges on sequence pac.surface_publication_decisions_publication_decision_id_seq from public, pac_app_runtime;
revoke all privileges on sequence pac.surface_change_events_event_id_seq from public, pac_app_runtime;

revoke all privileges on function pac.prevent_surface_history_change() from public, pac_app_runtime;
revoke all privileges on function pac.assert_surface_request(text, text, boolean) from public, pac_app_runtime;
revoke all privileges on function pac.assert_valid_surface_document(text, text, jsonb) from public, pac_app_runtime;
revoke all privileges on function pac.enforce_surface_definition_contract() from public, pac_app_runtime;
revoke all privileges on function pac.enforce_surface_revision_contract() from public, pac_app_runtime;
revoke all privileges on function pac.enforce_surface_publication_gate() from public, pac_app_runtime;
revoke all privileges on function pac.read_surface_publication(text, text) from public;
revoke all privileges on function pac.read_surface_editing_state(text, text) from public;
revoke all privileges on function pac.create_surface_draft(text, text, uuid, jsonb, text) from public;
revoke all privileges on function pac.record_surface_review(text, text, uuid, text, text, uuid, text) from public;
revoke all privileges on function pac.publish_surface_draft(text, text, uuid, bigint, text) from public;
revoke all privileges on function pac.withdraw_surface_publication(text, text, uuid, bigint, text) from public;
revoke all privileges on function pac.resume_surface_inheritance(text, text, bigint, text) from public;
revoke all privileges on function pac.restore_surface_revision(text, text, uuid, bigint, text) from public;

grant execute on function pac.read_surface_publication(text, text) to pac_app_runtime;
grant execute on function pac.read_surface_editing_state(text, text) to pac_app_runtime;
grant execute on function pac.create_surface_draft(text, text, uuid, jsonb, text) to pac_app_runtime;
grant execute on function pac.record_surface_review(text, text, uuid, text, text, uuid, text) to pac_app_runtime;
grant execute on function pac.publish_surface_draft(text, text, uuid, bigint, text) to pac_app_runtime;
grant execute on function pac.withdraw_surface_publication(text, text, uuid, bigint, text) to pac_app_runtime;
grant execute on function pac.resume_surface_inheritance(text, text, bigint, text) to pac_app_runtime;
grant execute on function pac.restore_surface_revision(text, text, uuid, bigint, text) to pac_app_runtime;

comment on table pac.surface_definitions is
  'Migration-registered staff wording fields. Browser requests cannot add fields or change components, code, protected assets, or the DHS logo.';
comment on table pac.surface_revisions is
  'Immutable complete staff wording documents, separated by exact One DHS or DSD scope.';
comment on function pac.read_surface_publication(text, text) is
  'Reads one effective approved staff wording document, honoring DSD publish, withdraw, and inheritance decisions.';

commit;
